/**
  Dr. No (1962)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('18fda8f7-10a4-4ad4-84a9-4573dd8704d4'),
       1,
       'Dr. No',
       'When British station chief John Strangways is murdered in Jamaica, MI6 agent James Bond, code named 007, is sent to investigate. He uncovers a plot by Dr. Julius No, a reclusive scientist working for the criminal organization SPECTRE, who is using a high-powered radio beam weapon to disrupt American space launches from Cape Canaveral. Joining forces with CIA agent Felix Leiter and shell diver Honey Ryder, Bond infiltrates Dr. No’s fortified island base on Crab Key, overloads the nuclear reactor powering the weapon, kills Dr. No, and escapes with Ryder before the entire facility explodes.',
       'The story opens in Kingston, Jamaica, where John Strangways, the chief of MI6''s station, and his secretary are assassinated by three hitmen posing as blind beggars. In London, M summons James Bond and assigns him to investigate Strangways'' disappearance. Bond is informed that Strangways was helping the CIA track mysterious radio signal jamming that was interfering with American rocket tests launched from Cape Canaveral. M orders Bond to replace his preferred Beretta pistol with a Walther PPK before he departs. Upon arriving in Kingston, Bond immediately notices he is being watched and followed. A driver claiming to represent Government House attempts to pick him up, but Bond realizes the driver is an enemy agent. After a brief fistfight, the driver commits suicide with a cyanide-laced cigarette. Bond inspects Strangways'' home and finds a receipt signed by a local fisherman named Quarrel. Bond tracks Quarrel down, and after a tense confrontation driven by mutual suspicion, he meets CIA agent Felix Leiter, who reveals that Quarrel is working with them. Quarrel explains that Strangways had regularly hired him to collect mineral and soil samples from Crab Key, a heavily guarded, restricted island owned by the secretive Dr. Julius No, whom locals fear due to rumors of a deadly dragon guarding the shores. Bond pursues local leads and uncovers Miss Taro, a secretary at Government House who is secretly a double agent for Dr. No. She attempts to set an ambush for Bond at her mountain home, but Bond outsmarts her, turns her over to the police, and sets a trap for an assassin named Professor Dent. Dent arrives to shoot Bond after a previous attempt using a venomous tarantula failed, but Bond disarms Dent and executes him. Bond and Quarrel sail under cover of night to Crab Key. The next morning on the beach, Bond meets Honey Ryder, a local beachcomber collecting sea shells. Dr. No''s guards quickly spot them, forcing the trio into the island''s swampy interior. That night, they encounter Dr. No''s legendary dragon, which is revealed to be an armored, flame-throwing swamp vehicle. Quarrel is killed in the attack, and Bond and Ryder are captured. Due to radioactive contamination in the swamp, they are forced into a decontamination facility before being placed in luxury accommodations in Dr. No''s subterranean compound. They are introduced to Dr. Julius No, a brilliant nuclear physicist who lost his natural hands to radiation exposure and now has powerful prosthetic metal hands. Dr. No explains that he joined SPECTRE, a global criminal organization, after his scientific services were rejected by both the United States and the Soviet Union. He plans to disrupt an upcoming Project Mercury space launch using his radio beam weapon to demonstrate SPECTRE''s power. Dr. No tries to recruit Bond into the organization, but Bond refuses. Bond is beaten and locked in a cell, while Ryder is separated and sent away. Bond manages to escape his cell by crawling through a high-voltage ventilation shaft. He steals a radiation protective suit, disguises himself, and slips into the main control room just as Dr. No begins powering up the beam to interfere with the rocket launch. Bond tampers with the reactor controls, forcing the system into an irrecoverable meltdown. Dr. No attacks Bond on the reactor platform, but during the struggle, Bond knocks Dr. No into the boiling, radioactive coolant pool. Unable to gain traction with his mechanical hands, Dr. No sinks to his death. As the facility alarms sound and workers flee, Bond finds and rescues Honey Ryder. They escape in a motorboat seconds before the base explodes, floating at sea until Felix Leiter and the Royal Navy pick them up.',
       'https://www.youtube.com/watch?v=H8u0962-baU',
       '5 October 1962, London Pavilion Cinema, London',
       UUID_TO_BIN('1bc6e9fc-b032-4ed0-b7ee-eca46ab85ecd'),
       'Sean Connery',
       UUID_TO_BIN('2d941726-5f84-4ab5-a5d0-1bd79b14fae4'),
       'Jamaica; Pinewood Studios, Bucks, UK',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  From Russia With Love (1963)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8316df48-88e6-43e3-aaa7-1c0d1ff93f82'),
       2,
       'From Russia With Love',
       'Seeking revenge for the death of Dr. No, the global criminal organization SPECTRE devises a master plan to assassinate James Bond and acquire a coveted Soviet Lektor decoding device. SPECTRE operative Rosa Klebb tricks a naive Soviet cipher clerk named Tatiana Romanova into believing she is defecting with the machine solely to be with Bond. MI6 sends 007 to Istanbul to retrieve Tatiana and the Lektor, leading to a deadly game of cat and mouse aboard the Orient Express against SPECTRE''s ruthless assassin Red Grant. Bond outsmarts his pursuers, secures the decoder, and eliminates SPECTRE''s agents before successfully escaping.',
       'The story begins as SPECTRE, seeking vengeance against MI6 for the death of Dr. No, devises a elaborate scheme crafted by their master strategist, Kronsteen. The plot aims to achieve two goals: steal a valuable Soviet Lektor encryption machine and humiliate MI6 by luring James Bond into a trap and executing him. SPECTRE leader Ernst Stavro Blofeld assigns former SMERSH chief Rosa Klebb to head the mission. Klebb recruits Tatiana Romanova, a young cipher clerk working at the Soviet embassy in Istanbul, convincing her that she is performing a secret mission for her country. Tatiana is instructed to offer the British secret service a Lektor machine on the condition that James Bond himself comes to Istanbul to assist her defection. In London, M informs Bond of the offer. Although MI6 suspects a trap, the potential prize of obtaining a working Soviet decoder is too significant to ignore, and Bond is dispatched to Turkey equipped with a specialized briefcase containing hidden weapons and survival gear from Q Branch. In Istanbul, Bond meets Kerim Bey, the head of MI6''s station in the city. Shortly after Bond''s arrival, tensions between British and Soviet intelligence escalate due to bombings engineered behind the scenes by SPECTRE to provoke conflict. After surviving an attack on a Gypsy camp arranged by Soviet-backed assassins, Kerim Bey helps Bond locate and spy on the Soviet embassy using an underground periscope. Bond meets Tatiana, who hands over plans of the embassy to facilitate their theft of the Lektor. Bond and Kerim Bey successfully steal the machine during a staged explosion at the embassy, and they immediately board the Orient Express to flee the country alongside Tatiana. Unknown to them, SPECTRE assassin Donald "Red" Grant is also aboard the train, silently tracking their movements and eliminating anyone who interferes. Grant kills both a Soviet agent following the group and Kerim Bey inside his compartment, staging the scene to make it appear as a mutual murder. At a train stop in Zagreb, Grant poses as a fellow British agent named Nash, whom he has already murdered, and joins Bond in his compartment. Grant drugs Tatiana''s wine, knocking her out, and then holds Bond at gunpoint. Grant smugly reveals SPECTRE''s entire scheme, explaining that he will kill Bond, stage the scene as a murder-suicide involving Tatiana, and blackmail MI6 with compromising film recordings of Bond and Tatiana. Bond tricks Grant into opening his Q Branch briefcase, triggering a tear gas trap concealed within. The two engage in a brutal, tight-quarters fight inside the train compartment, which ends when Bond overpowers Grant and strangles him with his own garrote wire. Bond steals a truck from Grant''s planned getaway route and escapes with the unconscious Tatiana and the Lektor. They face a series of SPECTRE attacks during their escape, including an assault by armed helicopters and a high-speed chase involving speedboats in international waters, both of which Bond successfully thwarts using Grant''s discarded weapons and fuel drums. Upon reaching a hotel in Venice, Rosa Klebb disguises herself as a maid and attempts to steal back the Lektor while executing Bond with a venomous blade hidden in her shoe. Tatiana intervenes and shoots Klebb, saving Bond''s life. With the threat eliminated and the Lektor secured, Bond and Tatiana share a romantic moment aboard a gondola as they throw the compromising film recordings into the canal.',
       'https://www.youtube.com/watch?v=XbYsb9sThaY',
       '10 October 1963, Odeon Leicester Square, London',
       UUID_TO_BIN('f3477c0d-bfdd-49b9-95a0-8144b9646ce2'),
       'Sean Connery',
       UUID_TO_BIN('2d941726-5f84-4ab5-a5d0-1bd79b14fae4'),
       'Istanbul, Turkey; Venice, Italy; Scotland and Pinewood Studios, UK',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Goldfinger (1964)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2dc921ab-7bb2-4fc1-a3f9-ea22bc73094e'),
       3,
       'Goldfinger',
       'MI6 agent James Bond is tasked with investigating Auric Goldfinger, a wealthy bullion tycoon obsessed with gold. Bond uncovers Operation Grand Slam, a sinister plot by Goldfinger to detonate a dirty nuclear device inside Fort Knox, which would irradiate the United States'' gold reserves, render them useless, and skyrocket the value of Goldfinger''s own vast holdings. Joined by pilot Pussy Galore, whom Bond convinces to turn against her employer, 007 infiltrates Fort Knox, defeats Goldfinger''s deadly henchman Oddjob, defuses the atomic bomb, and ultimately kills Goldfinger after a final struggle aboard an airplane.',
       'The film opens with James Bond completing a sabotage mission in Latin America before vacationing in Miami Beach. There, his supervisor M instructs him to observe Auric Goldfinger, an international gold magnate suspected of smuggling. Bond exposes Goldfinger cheating at cards with the help of a woman named Jill Masterson. Bond seduces Jill, but Goldfinger''s imposing henchman Oddjob knocks Bond unconscious. When Bond wakes up, he finds Jill dead, completely painted in gold and killed by epidermal suffocation as a message from Goldfinger. Back in London, Bond is formally briefed by M and the Bank of England about Goldfinger''s suspicious international movements of gold. Armed with an option-loaded Aston Martin DB5 equipped with tracking devices and ejector seats from Q Branch, Bond follows Goldfinger to Switzerland. While spying on Goldfinger''s factory, Bond encounters Tilly Masterson, Jill''s sister, who is seeking revenge. They trigger Goldfinger''s alarms, leading to a high-speed chase where Tilly is killed by Oddjob''s lethal steel-rimmed bowler hat, and Bond is captured. Bond is strapped to a table beneath a industrial laser beam, but he narrowly saves himself from being cut in half by bluffing that MI6 knows about Goldfinger''s secret plan, Operation Grand Slam. Goldfinger transports the captive Bond to his horse ranch in Kentucky. Bond manages to overhear Goldfinger pitching Operation Grand Slam to a group of American mobsters, whom Goldfinger subsequently murders with poison gas once he has their financial backing. Goldfinger reveals that he does not intend to steal the gold from Fort Knox, as moving that much metal would be physically impossible. Instead, he plans to disperse nerve gas over Fort Knox to eliminate the military personnel, break into the vault, and detonate a dirty Chinese nuclear device. The radiation would render the American gold reserve unusable for nearly a century, drastically increasing the value of Goldfinger''s personal gold hoard and plunging the Western economy into chaos. Bond is placed under the guard of Pussy Galore, Goldfinger''s personal pilot who leads an all-female flying squadron. Bond uses his charm to sway Pussy Galore away from her criminal loyalties, convincing her to secretly alert the United States government and replace the lethal nerve gas in her planes with an inert sleeping gas. When Goldfinger''s planes fly over Fort Knox and spray the troops, the soldiers play dead, allowing Goldfinger''s forces to enter the vault unhindered and seal Bond inside with the ticking atomic bomb. Once inside the vault, the military surrounds Goldfinger''s army, revealing the trap. Goldfinger sheds his disguise as a military officer and escapes, leaving Oddjob behind to protect the bomb. Bond engages in a desperate fight against the extraordinarily strong Oddjob inside the vault, eventually electrocuting the henchman using a severed power cable and Oddjob''s own metal hat stuck in a metal grille. An American specialist arrives with seconds to spare and switches off the nuclear timer at seven seconds. Believing he is safe, Bond boards a private jet to meet the President, only to find Goldfinger hijacking the plane. During a struggle for a gun, a shot ruptures a window, causing a sudden depressurization that blows Goldfinger out of the aircraft to his death. Bond and Pussy Galore parachute to safety together from the falling plane before it crashes.',
       'https://www.youtube.com/watch?v=aXBjz4-oEqk',
       '17 September 1964, Odeon Leicester Square, London',
       UUID_TO_BIN('d28dd94f-79ed-4985-9203-1e330868bb66'),
       'Sean Connery',
       UUID_TO_BIN('1a8eeb34-1968-47a9-876f-4e4f7810f508'),
       'Switzerland; Kentucky and Miami, USA, Pinewood Studios, Stoke Poges and London, UK',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Thunderball (1965)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('5a914395-9ddc-451e-8231-f14cc3490d94'),
       4,
       'Thunderball',
       'When the global terrorist organization SPECTRE hijacks two atomic bombs from a NATO aircraft and demands a ransom of one hundred million pounds under the threat of destroying a major city, MI6 activates all Double-0 agents. James Bond follows a lead to the Bahamas, where he targets SPECTRE''s second-in-command, Emilio Largo. With the help of CIA agent Felix Leiter and Domino Derval, the sister of the murdered pilot who flew the stolen jet, Bond locates the submerged bombs, engages Largo''s underwater army in a massive battle, stops the nuclear strike, and defeats Largo before he can escape.',
       'The film opens as James Bond attends the funeral of a SPECTRE operative in France, only to uncover that the operative faked his death; Bond kills him and escapes using a jetpack. Meanwhile, in Paris, SPECTRE''s chief strategist Emilio Largo presents a extortion scheme to top commander Ernst Stavro Blofeld. SPECTRE operative Count Lippe uses plastic surgery to alter an assassin named Angelo to impersonate François Derval, a NATO pilot tasked with flying a Vulcan bomber loaded with two atomic weapons. During a training exercise, Angelo murders Derval, takes his place on the flight, hijacks the bomber, and ditches it in shallow waters near the Bahamas. Angelo is then betrayed and killed by Largo, while SPECTRE hides the nuclear weapons under the ocean floor. SPECTRE sends a ransom demand to NATO threatening to destroy a major city in the United States or the United Kingdom unless one hundred million pounds in un-cut diamonds is paid. MI6 assigns all 00 agents to Operation Thunderball. Bond notices a photograph of the deceased pilot François Derval at the briefing and recognizes him from a recent stay at a health clinic where Bond had crossed paths with Count Lippe. Bond requests to be assigned to Nassau in the Bahamas, suspecting Derval''s sister, Domino, might be a connection to the case. In Nassau, Bond meets Domino Derval and discovers she is the mistress of Emilio Largo, a wealthy philanthropist who is secretly SPECTRE''s Number Two. Bond allies with CIA agent Felix Leiter and receives advanced underwater equipment from Q. While searching the waters off Largo''s estate, Bond locates the submerged NATO bomber hidden under camouflage netting, confirming that the nuclear warheads have been retrieved by Largo''s men. Bond informs Domino that her brother was murdered by Largo, winning her loyalty; she agrees to help Bond search Largo''s yacht, the Disco Volante, using a Geiger counter to track the atomic bombs. Domino is discovered by Largo while searching the yacht and is held prisoner, but not before she alerts Bond that the bombs are being moved. Largo''s force prepares to transport one of the warheads to target Miami, Florida. Bond contacts Felix Leiter, who alerts the United States Coast Guard. A massive underwater battle ensues in the waters off the coast between Largo''s armed scuba divers and a unit of US Navy SEALs drop-inserted into the sea. Bond joins the fight, using specialized underwater propulsion gear and weapons to help decimate Largo''s force and secure the warheads. Largo escapes to his yacht with his remaining men, planning to detonate the remaining warhead. Bond sneaks aboard the fast-moving vessel, resulting in a brutal hand-to-hand fight with Largo in the ship''s wheelhouse. Just as Largo gains the upper hand and prepares to shoot Bond, Domino appears and kills Largo with a spear gun, avenging her brother. Bond and Domino jump clear of the Disco Volante moments before the vessel runs aground on a reef and explodes. Floating together in a life raft, Bond and Domino are scooped up into the air by a CIA rescue plane using a skyhook system.',
       'https://www.youtube.com/watch?v=Y7XtbjNdWWI',
       '9 December 1965, Hibiya Cinema, Tokyo, Japan',
       UUID_TO_BIN('51db80e9-a59b-4431-9b0a-9a2957eb910f'),
       'Sean Connery',
       UUID_TO_BIN('2d941726-5f84-4ab5-a5d0-1bd79b14fae4'),
       'Pinewood Studios and London, UK; France; Nassau, Bahamas; Miami, Florida, USA',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  You Only Live Twice (1967)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('b545a06f-025d-4dc6-b454-bc13782630ab'),
       5,
       'You Only Live Twice',
       'When American and Soviet spacecraft mysteriously vanish in orbit, bringing the two superpowers to the brink of nuclear war, MI6 fakes James Bond''s death so he can covertly investigate the source of the hijackings in Japan. Working alongside ninja leader Tiger Tanaka and Japanese agent Aki, Bond traces the operations to a hidden base inside a hollowed-out volcano operated by SPECTRE leader Ernst Stavro Blofeld, who is being paid by a rogue foreign power to spark World War III. Bond disguises himself, infiltrates the fortress, leads a ninja assault to destroy the base, and stops Blofeld''s space capsule before it can trigger global war.',
       'The film begins in Earth orbit, where an American Gemini space capsule is swallowed whole by a mysterious, larger spacecraft, causing the death of an astronaut. The United States accuses the Soviet Union of space piracy, while the Soviets deny involvement. World War III threatens to break out unless the culprit is identified before the next American launch. British intelligence detects that the mysterious spacecraft landed somewhere in the Sea of Japan, leading MI6 to suspect a third party is attempting to provoke a war between the superpowers. To allow James Bond to operate without drawing the enemy''s attention, MI6 fakes his murder in Hong Kong and buries him at sea, after which Bond is secretly revived and dispatched to Tokyo. In Japan, Bond contacts Aki, an operative working for Tiger Tanaka, the head of the Japanese Secret Service. Aki introduces Bond to Tanaka, who provides Bond with intelligence and resources. Bond investigates Osato Chemicals, a Japanese firm suspected of supplying materials to the hijackers. Bond breaks into the company''s offices, steals secret documents, and survives multiple assassination attempts with the help of Aki. Bond eventually meets the firm''s head, Mr. Osato, and his lethal assistant, Helga Brandt. After Bond SEDUCES Brandt to escape execution, she attempts to blow up his plane, but Bond lands safely, while a disappointed Blofeld executes Brandt by dropping her into a pool of piranhas. Bond travels to the remote Kobe docks, where he discovers a ship named the Ning-Po carrying contraband liquid oxygen, a vital rocket fuel. Bond flies a armed autogyro named Little Nellie, provided by Q, over the local coastal mountains to search for the launch site and engages in a dogfight with four armed helicopters. Meanwhile, a Soviet spacecraft is hijacked in orbit by the same mysterious vessel, driving international tensions to a breaking point as the United States prepares to launch its next capsule with a strict deadline. To infiltrate the suspicious fishing village near the volcanic islands where the ship was sighted, Bond undergoes a physical transformation to disguise himself as a local Japanese fisherman and enters a staged marriage with Kissy Suzuki, a female ninja diver. Aki is tragically murdered by a SPECTRE assassin who drops poison down a thread while she sleeps beside Bond, leaving Kissy to assist Bond in her place. Kissy guides Bond to a dormant volcano, where they discover that the crater is actually a disguised sliding roof hiding a vast, high-tech subterranean launch pad. Bond sneaks into the volcano base, where he discovers the hijacked space capsules and frees the captured American and Soviet astronauts. However, Bond is captured and brought before Ernst Stavro Blofeld, the leader of SPECTRE. Blofeld reveals that SPECTRE is being paid by a foreign superpower to start a war that will leave SPECTRE to rule the aftermath. As Blofeld prepares to launch his interceptor rocket to swallow the new American capsule and trigger World War III, Kissy alerts Tiger Tanaka, who arrives with a battalion of ninjas. Tanaka''s ninjas scale the volcano and blast open the crater roof, descending into the base under heavy gunfire. A massive battle breaks out inside the compound between the ninjas and SPECTRE''s heavily armed private army. Amid the chaos, Bond fights his way into the control room and detonates the self-destruct mechanism of Blofeld''s interceptor spacecraft in orbit just seconds before it can capture the American capsule, preventing nuclear war. Blofeld activates the volcano''s self-destruct sequence and escapes through a private tunnel. Bond, Kissy, Tanaka, and the surviving ninjas escape through underwater tunnels into the ocean as the volcano erupts, destroying the base. Floating in an inflatable life raft, Bond and Kissy share a romantic moment as a British submarine surfaces beneath them to pick them up.',
       'https://www.youtube.com/watch?v=iDWRdRMnUFc',
       '12 June 1967, Odeon Leicester Square, London',
       UUID_TO_BIN('2a2d28c0-6343-437c-9294-47a6405a1847'),
       'Sean Connery',
       UUID_TO_BIN('b0ea2235-7998-4674-8824-35b5250b9901'),
       'Pinewood Studios, UK; Hong Kong, China; Japan; Bahamas; Spain',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  On Her Majesty's Secret Service (1969)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('4a3515f9-577b-412c-8123-53f232e239ee'),
       6,
       'On Her Majesty''s Secret Service',
       'While continuing his tireless search for Ernst Stavro Blofeld, James Bond saves a troubled young woman named Tracy di Vicenzo from suicide and earns the respect of her father, a powerful European crime boss. In exchange for Bond considering marrying his daughter, the mob chief reveals Blofeld''s secret hideout at a research clinic in the Swiss Alps. Infiltrating the facility disguised as a genealogist, Bond discovers Blofeld''s plot to unleash a deadly biological weapon across the world using hypnotized young women. Bond escapes, teams up with his new bride Tracy and her father''s forces to destroy Blofeld''s lair, but the mission ends in sudden heartbreak shortly after Bond and Tracy marry.',
       'The film opens in Portugal, where James Bond rescues a distressed young woman named Contessa Teresa "Tracy" di Vicenzo from taking her own life on a beach. Bond later meets her father, Marc-Ange Draco, the head of the Unione Corse, a powerful European crime syndicate. Impressed by Bond, Draco offers a massive financial reward if Bond marries Tracy, believing marriage will stabilize her fragile life. Bond declines the money but agrees to court Tracy if Draco uses his vast underworld network to help him locate Ernst Stavro Blofeld, the leader of SPECTRE who has gone into hiding. Draco''s intelligence leads Bond to the College of Arms in London. SPECTRE leader Blofeld is attempting to claim the noble title of Count Balthazar de Bleuchamp, requiring an official genealogist to inspect his ancestral credentials. Disguised as Sir Hilary Bray, a representative from the College of Arms, Bond travels to Blofeld''s secluded, high-altitude allergy research clinic atop Piz Gloria in the Swiss Alps. Inside the facility, Bond discovers that Blofeld, managed by his stern henchwoman Irma Bunt, is brainwashing twelve beautiful young women from around the world. Under hypnosis, these women are instructed to act as unwitting biological vectors, distributing a deadly virus capable of wiping out global agriculture and livestock unless Blofeld is granted amnesty for past crimes and recognized in his title. Bond''s cover is eventually blown after he seduces multiple clinic patients to gather information. Blofeld captures Bond and reveals his biological blackmail plot against the United Nations. Bond executes a daring escape from the mountain stronghold, descending the icy peak on skis while pursued by Blofeld''s heavily armed mercenaries. Reaching the village below, Bond meets Tracy, who has followed him to Switzerland. She uses her driving skills to help Bond evade Blofeld''s henchmen during a thrilling car chase through an ice stock rally. The next day, while fleeing on skis, an avalanche triggered by Blofeld buries them, allowing Blofeld to capture Tracy while Bond is left for dead. Returning to London, M refuses to authorize an official military strike on Piz Gloria, prioritizing diplomatic negotiations over a direct attack. Unwilling to leave Tracy behind, Bond recruits Draco and his syndicate army to mount a private rescue operation. Flying helicopters disguised as Red Cross transports, Bond and Draco''s men launch a surprise assault on Piz Gloria. A fierce battle breaks out, allowing Bond to rescue Tracy and set explosives that destroy the facility. Blofeld escapes in a bobsled, and Bond pursues him, leading to a high-speed fight in the bobsled run that leaves Blofeld entangled in low-hanging tree branches, seemingly snapping his neck. With the threat neutralized, Bond and Tracy marry in a joyous ceremony in Portugal, surrounded by friends including M, Q, and Moneypenny. As the newlyweds stop by the side of the road in Bond''s Aston Martin to remove flower decorations, a passing car driven by Irma Bunt with Blofeld at the wheel opens fire in a drive-by shooting. Bond survives unharmed, but discovers that Tracy has been killed by a bullet to the head. Heartbroken, Bond cradles his deceased wife in his arms as a traffic officer arrives, reassuring the officer that they are fine because they have all the time in the world.',
       'https://www.youtube.com/watch?v=rbeOmrpmIp0',
       '18 December 1969, Odeon Leicester Square, London',
       UUID_TO_BIN('ecad3278-91e6-4a81-b714-2719098a548b'),
        'George Lazenby',
       UUID_TO_BIN('81894653-2e54-4e01-b015-ef029e938d34'),
        'London, Pinewood Studios, UK; Switzerland; Portugal',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Diamonds Are Forever (1971)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('9c415115-9be6-4f4f-8495-6f26b4fc60cb'),
       7,
       'Diamonds Are Forever',
       'Seeking revenge for the murder of his wife, James Bond tracks down and seemingly kills his archenemy Ernst Stavro Blofeld before taking on an undercover assignment to investigate a massive international diamond smuggling ring. Posing as smuggler Peter Franks, Bond travels from Amsterdam to Las Vegas, where he joins forces with smuggler Tiffany Case. Bond discovers that Blofeld is actually alive and hoarding smuggled diamonds to power a giant laser satellite in Earth''s orbit. Blofeld plans to use the orbital laser to destroy major nuclear arsenals and extort world powers, but Bond infiltrates Blofeld''s offshore oil rig command center, destroys the satellite controls, and thwarts SPECTRE once again.',
       'The film opens with James Bond on a relentless international hunt to avenge the murder of his wife, Tracy. Bond tracks Ernst Stavro Blofeld to a secret laboratory where surgical body doubles are being created. After confronting Blofeld and drowning him in a vat of boiling mud, Bond believes he has finally eliminated his sworn enemy. Back in London, M reassigns Bond to investigate a massive diamond smuggling operation that is hoarding stockpiles of diamonds rather than selling them, threatening to collapse the global market. Disguised as professional smuggler Peter Franks, Bond travels to Amsterdam to make contact with local operative Tiffany Case. When the real Peter Franks escapes custody and arrives on the scene, Bond is forced to kill him in a brutal elevator fight and swap identities to protect his cover. Bond uses Franks'' corpse to smuggle a cache of diamonds into the United States, hiding the gems inside the body. In Las Vegas, Bond meets CIA agent Felix Leiter and transfers the diamonds to a mortuary run by the shady Shady Tree. Along the way, Bond crosses paths with Mr. Wint and Mr. Kidd, a pair of eccentric and ruthless SPECTRE assassins who are systematically murdering everyone involved in the supply chain to eliminate witnesses. Bond tracks the diamonds to the Whyte House, a lavish casino hotel owned by Willard Whyte, a reclusive billionaire who has not been seen in public for years. Infiltrating Whyte''s high-tech research facility outside the city, Bond steals a moon buggy to escape security guards and discovers that scientific expert Dr. Metz is using the smuggled diamonds to construct an advanced satellite. Bond scales the outside of the casino penthouse to confront Whyte, only to discover two identical Blofelds. Bond kills one, which turns out to be another surgical body double, and is captured by the real Blofeld, who had been holding the real Willard Whyte captive and impersonating him using voice-synthesis technology. Blofeld locks Bond in the trunk of a car, and Mr. Wint and Mr. Kidd trap him inside an underground pipeline to die. Bond escapes the pipeline and rescues the real Willard Whyte with the help of CIA agents. Bond learns that Blofeld has already launched his satellite into Earth''s orbit. Powered by a laser amplified by the smuggled diamonds, the satellite demonstrates its terrifying power by destroying nuclear weapons stockpiles in the United States, the Soviet Union, and China. Blofeld then opens an international auction, offering sole nuclear supremacy to whichever country bids the highest. Tracking Blofeld''s communications, Bond and the CIA locate his operational headquarters on an oil rig off the coast of Baja California. Posing as a guest, Bond arrives at the rig with Tiffany Case, but Blofeld catches him trying to swap the satellite control tape. Bond alerts Leiter, who launches a massive United States Marine Corps helicopter attack on the oil rig. A fierce battle breaks out as soldiers assault the platform. Bond manages to regain control of the crane holding Blofeld''s escape midget submarine, swinging it into the control room to smash the satellite command systems and kill Blofeld. Bond and Tiffany escape the exploding oil rig and board a luxury cruise ship, where Bond outsmarts and kills Mr. Wint and Mr. Kidd when they attempt a final assassination during dinner, leaving Bond and Tiffany to enjoy their romantic voyage.',
       'https://www.youtube.com/watch?v=M5xtULTukaQ',
       '30 December 1971, Odeon Leicester Square, London',
       UUID_TO_BIN('6fc69b76-69d4-415b-ae28-381e609ce5db'),
       'Sean Connery',
       UUID_TO_BIN('1a8eeb34-1968-47a9-876f-4e4f7810f508'),
       'Las Vegas, Nevada; California; France; Amsterdam, Holland; Pinewood Studios, UK',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Live And Let Die (1973)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('bcbf8703-14fe-4999-a2cd-2336b91ca7a5'),
       8,
       'Live And Let Die',
       'When three British MI6 agents are mysteriously murdered in twenty-four hours, James Bond is dispatched to New York City, New Orleans, and the Caribbean island of San Monique to investigate. Bond discovers a connection between Dr. Kananga, the corrupt dictator of San Monique, and Mr. Big, a ruthless Harlem mob boss. The two men are actually the same person, planning to distribute two tons of free heroin across America to bankrupt rival drug cartels and create a massive monopoly. Guided by the fortune-telling tarot card reader Solitaire, Bond survives lethal encounters with voodoo cultists, alligators, and henchmen to destroy Kananga''s heroin fields and eliminate the dictator.',
       'The film begins with the sequential assassinations of three MI6 agents in New York City, New Orleans, and the Caribbean island nation of San Monique. In London, M personally visits James Bond''s apartment to assign him to investigate the deaths, which all seem connected to Dr. Kananga, the charismatic ruler of San Monique. Bond travels to New York City, where his CIA contact Felix Leiter is monitoring Kananga''s movements. Upon arrival, Bond''s driver is murdered by an assassin, causing a car crash. Bond tracks the killer''s trail to a Harlem restaurant owned by Mr. Big, a powerful African-American crime lord who controls the local underworld. At the restaurant, Bond meets Solitaire, a beautiful tarot card reader who possesses genuine psychic abilities that allow her to predict the future for Dr. Kananga, provided she remains a virgin. Bond is captured by Mr. Big''s men, but he manages to escape with the help of CIA agent Strutter. Suspecting a deeper connection between San Monique and Mr. Big, Bond travels to the Caribbean island. With the aid of local CIA operative Rosie Carver and Quarrel Jr., Bond explores the island and uncovers secret, heavily guarded poppy fields hidden behind camouflage netting. Bond tricks Solitaire into sleeping with him by using a rigged deck of tarot cards where every card indicates lovers, causing her to lose her psychic abilities and pledge her loyalty to him. Realizing that Kananga will execute Solitaire for losing her powers, Bond escapes the island with her and travels to New Orleans. There, Bond is ambushed and captured by Mr. Big''s operatives. Brought before Mr. Big, the mob boss peels off a realistic latex mask to reveal that he is actually Dr. Kananga. Kananga explains his master plan to manufacture tons of pure heroin on San Monique and distribute it for free through his Fillet of Soul restaurant chain across the United States. By giving away the drugs, he intends to double the number of addicts, drive rival cartels out of business, and establish a lucrative, absolute monopoly on the drug trade. Kananga leaves Bond to be fed to alligators at a Louisiana reptile farm run by his prosthetic-clawed henchman, Tee Hee. Bond outsmarts his captors by running across the backs of several alligators to reach safety. Bond steals a speedboat and leads local police and Kananga''s henchmen on a high-speed chase through the Louisiana bayous, destroying his pursuers'' boats and reuniting with Felix Leiter. Bond returns to San Monique to rescue Solitaire, who is slated to be executed in a sacrificial voodoo ceremony led by Baron Samedi, the island''s mysterious voodoo practitioner. Bond rescues Solitaire, disrupts the voodoo ritual, shoots Baron Samedi, and sets fire to Kananga''s massive hidden poppy fields. Bond and Solitaire then infiltrate Kananga''s underground lair beneath the island. Captured once more, they are tied to a platform suspended over a shark tank. Bond uses a hidden saw in his Rolex watch to cut his ropes and retrieves a compressed-gas pellet used for shark gun ammunition. During a struggle inside the tank room, Bond forces the compressed-gas pellet down Kananga''s throat, causing the dictator to inflate like a balloon, float to the ceiling, and explode. Bond and Solitaire escape the facility with Leiter''s help and board a train, where Bond defeats Tee Hee in a final fight by throwing him out a window, leaving Bond and Solitaire to enjoy their journey together.',
       'https://www.youtube.com/watch?v=uLgmsh15mew',
       '6 July 1973, Odeon Leicester Square, London',
       UUID_TO_BIN('2b4c0c1c-1e48-4e69-bbd9-d20f6970dda4'),
       'Roger Moore',
       UUID_TO_BIN('1a8eeb34-1968-47a9-876f-4e4f7810f508'),
       'New Orleans; Jamaica; Harlem, New York City; Pinewood Studios, England',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  The Man With The Golden Gun (1974)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3a6b6e28-5e31-4931-8c6f-8a5694877e54'),
       9,
       'The Man With The Golden Gun',
       'When MI6 receives a golden bullet engraved with 007''s code number, M relieves James Bond of his current mission to protect him from Francisco Scaramanga, the world''s most expensive and elusive hitman who uses a signature golden gun. Bond travels to Asia to track Scaramanga down and uncovers a plot involving the Solex Agitator, a revolutionary device capable of harnessing solar energy to solve the global energy crisis. Bond travels to Scaramanga''s private island in the South China Sea, where he faces the assassin in a deadly duel inside a bizarre funhouse, kills Scaramanga, retrieves the stolen technology, and escapes before the island facility explodes.',
       'The film opens on a secluded island in the South China Sea, where high-priced assassin Francisco Scaramanga practices his deadly skills in a funhouse, killing a mob hitman sent to challenge him. In London, MI6 receives a golden bullet inscribed with 007, indicating that Scaramanga, who charges one million dollars per target and leaves behind custom golden bullets, has targeted James Bond. To safeguard Bond, M relieves him of his current assignment to retrieve Gibson, a British scientist who has invented the Solex Agitator, a breakthrough device capable of converting solar power into infinite electrical energy. Determined to confront the threat, Bond sets off on an unsanctioned search for Scaramanga. Bond''s investigation leads him to Macau, where he tracks down the manufacturer of Scaramanga''s custom golden bullets. Bond follows the bullet supply to Andrea Anders, Scaramanga''s mistress, who admits that she sent the golden bullet to MI6 in London. She reveals that she wants Bond to kill Scaramanga so she can escape her abusive relationship with him. Bond follows Anders to Hong Kong, where he witnesses the assassination of Gibson outside a cabaret club. Scaramanga''s pint-sized henchman, Nick Nack, steals the Solex Agitator from Gibson''s body before the police arrive. Bond is arrested by local authorities but is rescued and brought to a hidden MI6 headquarters constructed inside the half-submerged wreck of the RMS Queen Elizabeth in Hong Kong harbor. Working alongside MI6 Assistant Mary Goodnight and local contact Hip, Bond investigates Hai Fat, a wealthy Thai industrialist suspected of financing Scaramanga. Bond infiltrates Hai Fat''s Bangkok estate disguised as Scaramanga, as few people know what the hitman looks like except that he has a third nipple. However, Hai Fat recognizes the fake third nipple and captures Bond. Scaramanga executes Hai Fat to seize full control of the Solex Agitator and the solar technology business. Bond escapes execution at a martial arts academy, leading local police and Scaramanga''s men on a high-speed boat chase through the canals of Bangkok. Bond arranges to meet Andrea Anders at a Muay Thai match to receive the stolen Solex Agitator, but he discovers her dead in her stadium seat, shot through the heart by Scaramanga. Bond retrieves the Solex Agitator from her purse and meets Scaramanga face-to-face in the crowded stadium. Scaramanga steals the device back and kidnaps Mary Goodnight, forcing her into the trunk of his car. Bond pursues Scaramanga in an AMC Hornet, performing a spectacular barrel-roll jump across a collapsed bridge, but Scaramanga converts his car into a flying vehicle and escapes with Goodnight to his secret island stronghold. Using a tracking signal placed in Goodnight''s car, Bond flies a small amphibious plane to Scaramanga''s island in Chinese territorial waters. Scaramanga greets Bond warmly and gives him a tour of his solar power plant, which uses the Solex Agitator to power a massive laser beam capable of destroying incoming aircraft. Over lunch, Scaramanga proposes a formal pistol duel to prove who is the ultimate killer. On the beach, the two men stand back-to-back and take ten paces, but Scaramanga vanishes into his complex funhouse. Bond follows him inside, navigating mirror tricks and mechanical traps. Bond poses as a wax mannequin of himself, catching Scaramanga off guard and shooting him dead. Meanwhile, Goodnight accidentally knocks a guard into a vat of liquid coolant, triggering a thermal reaction that threatens to blow up the base. Bond retrieves the Solex Agitator, saves Goodnight, and the two escape on Scaramanga''s automated junk boat, defeating a vengeful Nick Nack during their voyage home.',
       'https://www.youtube.com/watch?v=tiR2MwsPgQE',
       '19 December 1974, Odeon Leicester Square, London',
       UUID_TO_BIN('61465290-415d-47df-82a9-c000a23ffa16'),
       'Roger Moore',
       UUID_TO_BIN('1a8eeb34-1968-47a9-876f-4e4f7810f508'),
       'Macau; Hong Kong; Bangkok, Phuket, Thailand, Pinewood Studios, London, UK',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  The Spy Who Loved Me (1977)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('7774936e-04e5-4609-aa1d-a7b26d782947'),
       10,
       'The Spy Who Loved Me',
       'When British and Soviet nuclear submarines mysteriously vanish without a trace, MI6 agent James Bond and KGB agent Anya Amasova, code named Agent XXX, are forced into an uneasy alliance to investigate. They track the missing submarines to Karl Stromberg, a megalomaniacal reclusive shipping tycoon who operates out of a massive ocean station named Atlantis. Stromberg plans to launch the captured submarines'' nuclear missiles at Moscow and New York City to trigger a global holocaust and build a new underwater civilization. Accompanied by Anya, who vows to kill Bond after the mission to avenge her lover whom 007 killed on a past assignment, Bond infiltrates Stromberg''s fortress, thwarts the missile launches, defeats the steel-toothed assassin Jaws, and saves the day.',
       'The film opens in Austria, where James Bond escapes an ambush by Soviet assassins, killing one of them in a high-speed ski chase before parachuting to safety. In Moscow, KGB agent Anya Amasova learns that the man Bond killed was her lover. Meanwhile, two nuclear submarines—one British and one Soviet—vanish while on active patrol in the ocean. Due to the catastrophic nature of the disappearances, MI6 and the KGB agree to cooperate, assigning Bond and Anya to travel to Cairo to track down a stolen microfiche containing the tracking system used to locate the submerged submarines. In Egypt, Bond and Anya meet and compete to secure the microfiche from various black-market contacts. They cross paths with Jaws, a towering assassin with indestructible steel teeth employed by Karl Stromberg, a wealthy shipping magnate with a passion for the ocean. After Jaws murders their contacts, Bond and Anya team up and secure the microfiche, discovering that the tracking system was developed by Stromberg''s organisation. They travel to Sardinia to inspect Stromberg''s operations, posing as a marine biologist and his wife. There, they meet Stromberg aboard his aquatic base, Atlantis, and Bond suspects the tycoon is hiding a sinister plot behind his oceanographic research. Upon leaving Atlantis, Bond and Anya are chased by Stromberg''s henchmen in cars, a helicopter, and a armed sidecar. Bond drives his multi-purpose Lotus Esprit into the ocean, transforming the car into a submarine to destroy an attacking enemy submersible and Jaws'' vehicle. Bond and Anya dive beneath Stromberg''s supertanker, the Liparus, and confirm that the massive vessel uses a bow that opens underwater to swallow nuclear submarines whole. Before they can report their findings, Anya discovers that Bond was the agent who killed her lover in Austria. She vows to complete the mission, but promises to kill Bond the moment their assignment is finished. Bond and Anya board an American nuclear submarine to investigate the Liparus, but the supertanker captures their submarine as well. Inside the Liparus'' giant interior dock, Stromberg reveals his master plan to Bond and Anya: he intends to launch nuclear missiles from the captured British and Soviet submarines at New York City and Moscow, triggering a global nuclear war that will destroy surface civilization so he can establish a new world order under the sea. Stromberg departs for Atlantis with Anya as his prisoner, leaving his private army to guard the captured submarine crews. Bond breaks free and releases the imprisoned British, Soviet, and American sailors, leading a massive battle inside the supertanker''s dock against Stromberg''s guards. Bond uses the nuclear warhead from a missile to blast open the armored control room, where he re-programs the two launched submarines to target each other instead of the cities, destroying both in mid-ocean. Bond escapes the sinking Liparus aboard an American submarine and orders an attack on Atlantis. Bond travels to the underwater station on a jet ski to rescue Anya. He shoots Stromberg dead and drops Jaws into a shark tank, though the assassin bites the shark and survives. Bond and Anya escape Atlantis in an escape pod just as the US submarine torpedoes and destroys the base. Aboard the floating pod, Anya points a gun at Bond to fulfill her vow, but Bond sways her with his charm, leading her to forgive him as they are rescued.',
       'https://www.youtube.com/watch?v=Ve7v5kL3MeE',
       '7 July 1977, Odeon Leicester Square, London',
       UUID_TO_BIN('90b6d569-00f5-40c3-aa3d-a6ee0f40d313'),
       'Roger Moore',
       UUID_TO_BIN('b0ea2235-7998-4674-8824-35b5250b9901'),
       'Egypt; Sardinia; Canada; Malta; Scotland; Okinawa; Switzerland and Pinewood Studios, England. Underwater sequence filmed in Nassau, Bahamas',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Moonraker (1979)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3f511a7c-ee4c-4560-a621-2bd6b1b9faa8'),
       11,
       'Moonraker',
       'When a Moonraker space shuttle on loan to the United Kingdom is hijacked in mid-air, James Bond is assigned to investigate its manufacturer, the megalomaniacal billionaire Hugo Drax. Teaming up with CIA scientist Dr. Holly Goodhead, Bond follows a trail of deadly clues from California to Venice, Rio de Janeiro, and deep into the Amazon rainforest. He uncovers Drax''s insanity-driven plot to wipe out human life on Earth using a deadly nerve gas while preserving a handpicked, genetically perfect elite aboard a hidden, cloaked space station. Bond and Goodhead launch into orbit, infiltrate the space station, turn Drax''s henchman Jaws to their side, and destroy the station and nerve gas globes before humanity is annihilated.',
       'The film opens with a Moonraker space shuttle mounted on a Boeing 747 transport plane being hijacked mid-flight, destroying the plane in the process. James Bond is dispatched by M to investigate the shuttle''s manufacturer, Drax Industries, in California. Upon arrival, Bond meets the company''s owner, Hugo Drax, as well as astronaut Dr. Holly Goodhead, who Bond quickly realizes is an undercover CIA agent. After surviving an assassination attempt inside a centrifuge trainer orchestrated by Drax''s henchman Chang, Bond uncovers blueprints for a specialized glass vial manufactured in Venice. Bond travels to Venice, where he infiltrates the glassworks laboratory and discovers that Drax is synthesizing a deadly nerve gas derived from a rare orchid, which is lethal to humans but completely harmless to plants and animals. After defeating Chang in a high-stakes duel inside a clocktower, Bond follows the trail to Rio de Janeiro. Reunited with Holly Goodhead, Bond survives another attack atop the Sugarloaf Mountain cable car by Jaws, the steel-toothed assassin hired by Drax after Chang''s death. Bond and Goodhead are captured, but Bond escapes and pursues Drax deeper into the Amazon jungle. In the Amazon rainforest, Bond finds Drax''s secret launch facility hidden inside ancient ruins. He witnesses Drax launch several Moonraker shuttles to a giant, radar-stealth space station orbiting Earth. Bond and Goodhead disguise themselves as shuttle pilots and board one of the spacecraft to reach the station. Once aboard, Drax reveals his grand master plan: he intends to launch fifty nerve gas globes into Earth''s atmosphere, exterminating all human life on the planet. Drax plans to remain in space with a carefully selected group of genetically superior men and women, returning to Earth once the gas dissipates to establish a new human race under his absolute control. Bond manages to disable the space station''s radar-cloaking device, allowing United States radar systems on Earth to detect the massive station and launch a platoon of US Marines in an armed space shuttle to intervene. Bond also convinces Jaws to switch sides by pointing out that Drax''s vision of genetic perfection leaves no room for physical anomalies like Jaws or his new girlfriend Dolly. When the US Marines arrive, an epic laser battle ensues in outer space between the Marines and Drax''s guards around the station''s exterior. During the chaotic firefight inside the station, Bond pursues Drax, shoots him with a wrist-mounted poison dart, and ejects him through an airlock into the vacuum of space. Jaws helps Bond and Goodhead escape in a Moonraker shuttle equipped with a laser system just as the disintegrating space station breaks apart. Bond then manually targets and destroys the three nerve gas globes that had already been launched toward Earth''s atmosphere, successfully saving the planet before celebrating his victory in orbit with Holly.',
       'https://www.youtube.com/watch?v=iVgRdvGUy3o',
       '26 June 1979, Odeon Leicester Square, London',
       UUID_TO_BIN('8bca8fff-23d5-49c1-bec3-1a3686f3ce68'),
       'Roger Moore',
       UUID_TO_BIN('b0ea2235-7998-4674-8824-35b5250b9901'),
       'France; Brazil; Venice, Italy; Guatemala; the USA; England; outer space',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  For Your Eyes Only (1981)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('3eb1763c-ad84-401e-b877-aa687acf7549'),
       12,
       'For Your Eyes Only',
       'When British and Soviet nuclear submarines mysteriously vanish without a trace, MI6 agent James Bond and KGB agent Anya Amasova, code named Agent XXX, are forced into an uneasy alliance to investigate. They track the missing submarines to Karl Stromberg, a megalomaniacal reclusive shipping tycoon who operates out of a massive ocean station named Atlantis. Stromberg plans to launch the captured submarines'' nuclear missiles at Moscow and New York City to trigger a global holocaust and build a new underwater civilization. Accompanied by Anya, who vows to kill Bond after the mission to avenge her lover whom 007 killed on a past assignment, Bond infiltrates Stromberg''s fortress, thwarts the missile launches, defeats the steel-toothed assassin Jaws, and saves the day.',
       'The film opens in Austria, where James Bond escapes an ambush by Soviet assassins, killing one of them in a high-speed ski chase before parachuting to safety. In Moscow, KGB agent Anya Amasova learns that the man Bond killed was her lover. Meanwhile, two nuclear submarines—one British and one Soviet—vanish while on active patrol in the ocean. Due to the catastrophic nature of the disappearances, MI6 and the KGB agree to cooperate, assigning Bond and Anya to travel to Cairo to track down a stolen microfiche containing the tracking system used to locate the submerged submarines. In Egypt, Bond and Anya meet and compete to secure the microfiche from various black-market contacts. They cross paths with Jaws, a towering assassin with indestructible steel teeth employed by Karl Stromberg, a wealthy shipping magnate with a passion for the ocean. After Jaws murders their contacts, Bond and Anya team up and secure the microfiche, discovering that the tracking system was developed by Stromberg''s organisation. They travel to Sardinia to inspect Stromberg''s operations, posing as a marine biologist and his wife. There, they meet Stromberg aboard his aquatic base, Atlantis, and Bond suspects the tycoon is hiding a sinister plot behind his oceanographic research. Upon leaving Atlantis, Bond and Anya are chased by Stromberg''s henchmen in cars, a helicopter, and an armed sidecar. Bond drives his multi-purpose Lotus Esprit into the ocean, transforming the car into a submarine to destroy an attacking enemy submersible and Jaws'' vehicle. Bond and Anya dive beneath Stromberg''s supertanker, the Liparus, and confirm that the massive vessel uses a bow that opens underwater to swallow nuclear submarines whole. Before they can report their findings, Anya discovers that Bond was the agent who killed her lover in Austria. She vows to complete the mission, but promises to kill Bond the moment their assignment is finished. Bond and Anya board an American nuclear submarine to investigate the Liparus, but the supertanker captures their submarine as well. Inside the Liparus'' giant interior dock, Stromberg reveals his master plan to Bond and Anya: he intends to launch nuclear missiles from the captured British and Soviet submarines at New York City and Moscow, triggering a global nuclear war that will destroy surface civilization so he can establish a new world order under the sea. Stromberg departs for Atlantis with Anya as his prisoner, leaving his private army to guard the captured submarine crews. Bond breaks free and releases the imprisoned British, Soviet, and American sailors, leading a massive battle inside the supertanker''s dock against Stromberg''s guards. Bond uses the nuclear warhead from a missile to blast open the armored control room, where he re-programs the two launched submarines to target each other instead of the cities, destroying both in mid-ocean. Bond escapes the sinking Liparus aboard an American submarine and orders an attack on Atlantis. Bond travels to the underwater station on a jet ski to rescue Anya. He shoots Stromberg dead and drops Jaws into a shark tank, though the assassin bites the shark and survives. Bond and Anya escape Atlantis in an escape pod just as the US submarine torpedoes and destroys the base. Aboard the floating pod, Anya points a gun at Bond to fulfill her vow, but Bond sways her with his charm, leading her to forgive him as they are rescued.',
       'https://www.youtube.com/watch?v=DO2ntHC9jJM',
       '24 June 1981, Odeon Leicester Square, London',
       UUID_TO_BIN('b7f1b99a-9528-4d02-bd6d-e72b5b5a8318'),
       'Roger Moore',
       UUID_TO_BIN('29e4e57a-000c-486f-9bf7-4ce84899df6c'),
       'Cortina d’Ampezzo, Italy; Corfu, Kalambaka, Meteora, Greece; Stoke Poges, Pinewood Studios, England. Certain underwater scenes filmed in the Bahamas',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Octopussy (1983)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2375219d-1fc8-41f1-b47f-d8ee6b0edd6e'),
       13,
       'Octopussy',
       'When 009 is murdered while carrying a priceless fake Fabergé egg out of East Berlin, James Bond is assigned to investigate a theft network operating out of the Kremlin. Bond tracks the trail to exiled Afghan prince Kamal Khan and his wealthy partner, Octopussy, a glamorous cult leader who runs a circus troupe as a front for international smuggling. Bond uncovers a plot orchestrated by rogue Soviet General Orlov, who intends to detonate a nuclear warhead at a United States Air Force base in West Germany. Orlov expects the blast to look like an accident, forcing NATO into unilateral disarmament so the Soviet Union can invade Western Europe. Bond races against time to disarm the bomb, defeat Khan and his forces, and avert a global tragedy.',
       'The film begins with 009 fleeing East Berlin dressed as a circus clown, fatally wounded while carrying a forged Fabergé egg. Back in London, MI6 suspects that someone inside the Soviet government is stealing priceless treasures from the Kremlin art vaults to fund illegal operations. James Bond attends an auction in London where the genuine Fabergé egg is put up for sale. Bond bids against exiled Afghan prince Kamal Khan, surreptitiously swapping the real egg with the fake one carried by 009. Bond follows Khan to India to discover his motives and understand why he paid a massive sum for a forgery. In India, Bond confronts Khan during a high-stakes backgammon game, using the real Fabergé egg as leverage. Khan sends his towering bodyguard Gobinda and a horde of henchmen to kill Bond, but 007 escapes through the streets of Udaipur in a tuk-tuk. Bond infiltrates Khan''s floating island palace and meets Octopussy, a wealthy businesswoman, jewel smuggler, and leader of an all-female cult who operates an international touring circus. Octopussy reveals a personal connection to Bond, as her late father was a disgraced British officer whom Bond allowed to commit suicide honorably years prior. Bond uncovers that Khan has allied with General Orlov, a fanatical Soviet officer seeking to expand the Soviet empire. Orlov is stealing genuine Soviet treasures, replacing them with clever duplicates made by a master jeweler, and using Octopussy''s circus tour as a smuggling vessel across borders. However, Orlov secretly double-crosses Octopussy by replacing a container of smuggled jewels with a live nuclear warhead set to detonate at a circus performance hosted on a West Berlin United States Air Force base. Orlov calculates that the detonation will appear to be an accidental explosion of an American nuclear weapon, prompting European peace movements to demand complete nuclear disarmament and leaving Western Europe open to a Soviet ground invasion. Bond follows the circus train into East Germany, fighting off Orlov''s soldiers and assassins. Orlov is killed by East German border guards while attempting to catch the train, but Khan and Gobinda manage to arm the nuclear bomb hidden beneath the circus cannon platform. Bond sneaks into the West Berlin Air Force base disguised as a clown to bypass heavy security. He convinces the base commander of the imminent danger and successfully disarms the nuclear warhead with seconds to spare, preventing a catastrophic international disaster. Realizing that Khan exploited her circus, Octopussy joins forces with Bond to seek revenge. Octopussy leads her troupe of acrobatic warriors in a raid on Khan''s ancient palace stronghold in India. A battle ensues between Octopussy''s cult members and Khan''s mercenaries. Khan escapes aboard a vintage aircraft with Octopussy as his hostage, but Bond leaps onto the exterior of the plane as it takes off. Bond disables the engines from the outside and rescues Octopussy, jumping to safety on a cliffside before the plane crashes into a mountain, killing Khan and Gobinda. Bond recovers from his injuries alongside Octopussy aboard her private riverboat in India.',
       'https://www.youtube.com/watch?v=cwH3E4fNTzw',
       '6 June 1983, Odeon Leicester Square, London',
       UUID_TO_BIN('3da21e36-d36c-47c7-953d-39691b171fec'),
       'Roger Moore',
       UUID_TO_BIN('29e4e57a-000c-486f-9bf7-4ce84899df6c'),
       'Udaipur, India; Berlin, Germany; London, Nene Valley Railway, RAF Northholt base & Pinewood Studios, England; the USA',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  A View To A Kill (1985)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('c34f1b7b-3010-4155-8c40-bb4efb20dfb2'),
       14,
       'A View To A Kill',
       'When James Bond recovers a microchip from Siberia that is capable of surviving an electromagnetic pulse, MI6 points its attention toward Max Zorin, a ruthless industrialist and former KGB-engineered psychopath. Bond investigates Zorin across France and California, uncovering a plot code named Operation Main Strike. Zorin plans to detonate explosives along the San Andreas and Hayward faults, flooding Silicon Valley to destroy his competition and secure a global monopoly on microchip production. Joined by geologist Stacey Sutton and abandoned bodyguard May Day, Bond stops the flooding, defeats Zorin atop the Golden Gate Bridge, and saves California''s technology center.',
       'The film opens in Siberia, where James Bond retrieves a microchip from the body of fallen agent 002. After escaping Soviet soldiers on a improvised snowboard, Bond returns to London, where Q determines that the microchip is completely immune to the destructive effects of an electromagnetic pulse. MI6 traces the manufacturer to Zorin Industries, owned by Max Zorin, a enigmatic industrialist who dominates the tech market and horse-racing world. Bond travels to Paris with MI6 contact Tibbett to inspect Zorin''s racehorses and meets Zorin''s lethal bodyguard and lover, May Day. Bond suspects Zorin is using microchips to chemically boost his horses during races. Bond and Tibbett infiltrate Zorin''s French estate, where Bond discovers a secret underground laboratory confirming the horse-doping scheme. However, Zorin discovers Bond''s true identity and orders May Day to assassinate Tibbett in a car wash, while Bond is trapped in a sinking vehicle but survives by breathing air from a tire valve. Traveling to San Francisco, Bond meets state geologist Stacey Sutton, whose family oil business was forcibly bought out by Zorin. Together, Bond and Stacey realize Zorin''s real objective lies deep beneath the earth. Bond also learns from KGB General Gogol that Zorin was a product of Nazi medical experiments conducted by Dr. Carl Mortner, creating a brilliant but sociopathic mastermind. Bond and Stacey infiltrate San Francisco City Hall to view geological survey maps, but Zorin and May Day ambush them. Zorin kills the city planner, sets the building on fire, and frames Bond for the murder. Bond rescues Stacey from the burning elevator shaft and escapes police pursuit in a stolen fire truck. They trace Zorin''s operations to an abandoned silver mine near the San Andreas Fault. There, Zorin has set up a massive pumping operation to force water into the fault lines and trigger a catastrophic double earthquake, which would flood Silicon Valley, kill millions, and leave Zorin with a total global monopoly on microchip manufacturing. Inside the mine, Zorin betrays his own workforce, detonating explosives prematurely to flood the lower shafts with water and killing hundreds of his own miners. Disgusted by Zorin''s cold-blooded murder of his crew, May Day switches sides and joins forces with Bond. May Day uses her incredible strength to load the massive primary explosive device onto a mine cart, riding it out of the flooded cavern and sacrificing her life to detonate the bomb safely outside. Furious at the failure of his plan, Zorin kidnaps Stacey aboard his airship. Bond grabs onto one of the airship''s mooring ropes as it lifts off, riding it through the skies of San Francisco. The airship becomes snagged on the framework of the Golden Gate Bridge. Bond and Zorin engage in an intense axe fight on the bridge''s cables high above the bay. Bond overpowers Zorin, sending the villain plummeting off the bridge to his death in the waters below. Dr. Mortner attempts to blow up Bond with dynamite, but Bond cuts the mooring rope, causing the dynamite to fall back into the airship cab and explode. Bond and Stacey are rescued, and General Gogol visits M to present Bond with the Order of Lenin for saving Silicon Valley and its vital computer technology.',
       'https://www.youtube.com/watch?v=ZyvHssV3A68',
       '22 May 1985, Palace of Fine Arts, San Francisco, USA',
       UUID_TO_BIN('72cc60ab-0af2-4c29-bb21-d6df83fb9e19'),
       'Roger Moore',
       UUID_TO_BIN('29e4e57a-000c-486f-9bf7-4ce84899df6c'),
       'Jökulsárlón, Iceland; Paris and Chantilly, France; Vedretta di Scerscen Inferiore Glacier, Switzerland; London, Ascot, Amberly Chalk Farm and Pinewood Studios, England; San Francisco, USA',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  The Living Daylights (1987)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('dc7940f8-ad41-42b8-bf5d-da25e99752e4'),
       15,
       'The Living Daylights',
       'When defecting Soviet General Georgi Koskov is staged-kidnapped from an MI6 safehouse, James Bond is sent to eliminate the KGB chief Pushkin, whom Koskov claims has reinstated a lethal kill directive against Western agents. Bond intentionally spares a beautiful sniper named Kara Milovy in Bratislava and learns she is Koskov''s innocent girlfriend. Bond uncovers a conspiracy between Koskov and an eccentric American arms dealer named Brad Whitaker, who plan to use stolen MI6 funds to buy raw opium from local rebels in Soviet-occupied Afghanistan. Bond unites with Kara and local Afghan fighters to destroy the drug shipment, eliminate Koskov and Whitaker, and clear Pushkin''s name.',
       'The film opens in Gibraltar, where a training exercise for double-0 agents turns deadly when an unknown assassin murders MI6 operatives and leaves behind a message reading Smiert Spionam, meaning Death to Spies. In Bratislava, James Bond is tasked with aiding the defection of rogue KGB General Georgi Koskov. During the escape, Bond notices a sniper trained on Koskov, but realizing she is an amateur cellist rather than a professional killer, he shoots the rifle out of her hands instead of executing her. Bond successfully smuggles Koskov out of Czechoslovakia to England using a trans-Siberian gas pipeline. During debriefing at a secure MI6 country estate, Koskov tells British intelligence that General Pushkin, the newly appointed head of the KGB, has revived the ruthless Smiert Spionam campaign to execute enemy spies. Shortly after, Koskov is abducted from the safehouse by Necros, a lethal henchman posing as a milkman. M orders Bond to travel to Tangier to assassinate Pushkin to prevent further losses. However, Bond remains skeptical of Koskov''s story and decides to investigate the cellist sniper in Bratislava first, identifying her as Kara Milovy. Bond wins Kara''s trust by pretending to be a friend of Koskov, and together they flee Czechoslovakia into Austria while evading local police and KGB agents in a high-speed chase in Bond''s gadgets-equipped Lotus. In Vienna, Bond learns that Koskov''s staged defection was part of a larger deception. Traveling to Tangier, Bond confronts General Pushkin directly. Pushkin denies reinstating Smiert Spionam and reveals that Koskov is wanted by the KGB for embezzling millions in Soviet government funds. Bond and Pushkin stage Pushkin''s fake public assassination to fool Koskov into believing his scheme is progressing. However, Kara is tricked by Koskov into drugging Bond''s drink, leading to both Bond and Kara being captured and flown aboard a Soviet cargo plane to a Soviet airbase in Afghanistan. There, Koskov and his partner, an obsessed American arms dealer named Brad Whitaker, reveal their true plan. They are using the stolen Soviet funds to buy five hundred million dollars worth of raw opium from local Afghan rebels, intending to resell the drugs in North America to fund massive illegal weapons purchases. Bond and Kara escape their prison cell with the help of Kamran Shah, a leader in the local Mujahideen resistance. Bond infiltrates the airbase and hides a bomb inside the massive opium shipment loaded onto a Soviet transport plane. Bond hijacks the cargo plane as it takes off, leading to a perilous fight with Necros dangling out the open cargo bay door high above the desert. Bond cuts Necros loose and uses the plane''s bombs to support Kamran Shah''s fighters on the ground during a fierce battle against Soviet troops. Bond and Kara crash-land the plane and travel to Tangier, where Bond infiltrates Whitaker''s mansion, kills the arms dealer using a high-tech explosive keychain, and hands Koskov over to General Pushkin to be arrested and returned to Moscow.',
       'https://www.youtube.com/watch?v=kYnFd-0ewUg',
       '29 June 1987, Odeon Leicester Square, London',
       UUID_TO_BIN('ec6ff2ea-9213-47f9-9045-8ecbcfc90d58'),
       'Timothy Dalton',
       UUID_TO_BIN('29e4e57a-000c-486f-9bf7-4ce84899df6c'),
       'Ouarzazate, Tangier, Morocco; Gibraltar; sky over California, USA; Vienna, Weissensee, Austria; Oxfordshire, Beachy Head, RAF Wittering, Thetford, Norfolk, London and Pinewood Studios, England',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  License To Kill (1989)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('179f3409-d39d-437d-b998-79f150ee1b30'),
       16,
       'License To Kill',
       'After ruthless drug lord Franz Sanchez brutally attacks CIA agent Felix Leiter and murders Leiter''s newlywed wife Della, James Bond abandons his official duties to seek personal revenge. When M revokes his license to kill for going rogue, Bond operates as an independent agent, joining forces with DEA pilot Pam Bouvier and Sanchez''s mistress Lupe Lamora. Infiltrating Sanchez''s criminal empire in the fictional nation of Isthmus, Bond cleverly turns the drug lord against his own lieutenants from within. Bond dismantles Sanchez''s cocaine-smuggling network, defeats his army in a high-speed tanker chase, and sets Sanchez on fire using a gift from Felix, achieving personal justice for his friend.',
       'The film opens in Florida, where James Bond serves as the best man at the wedding of his longtime friend, CIA agent Felix Leiter, and his bride Della. En route to the ceremony, Bond and Leiter assist the DEA in capturing notorious drug kingpin Franz Sanchez, who has briefly entered US airspace. However, shortly after the wedding, a bribed DEA agent helps Sanchez escape custody. Sanchez immediately retaliates by sending his henchmen, led by Dario, to raid Leiter''s home. The operatives murder Della and feed Leiter to a shark, leaving him severely maimed and near death. Devastated by the attack, Bond vows to avenge his friends and begins investigating the crime independently. When M confronts Bond at a Key West marine research facility and demands he accept an assignment in Istanbul, Bond refuses. M revokes his license to kill and attempts to disarm him, but Bond escapes MI6 custody to go rogue. Guided by clues left at the crime scene, Bond traces the attack to Milton Krest, a marine contractor who uses his research vessel to smuggle Sanchez''s cocaine. Bond infiltrates Krest''s boat, sabotaging a major drug drop and stealing millions of dollars in cartel cash. Bond meets CIA informant and pilot Pam Bouvier at a local bar to secure transport into the Central American nation of Isthmus, where Sanchez operates with total political immunity. Despite being targeted by Sanchez''s assassins, Bond and Pam escape to Isthmus City. Posing as a wealthy hitman looking for employment, Bond deposits his stolen cartel cash into Sanchez''s bank, catching the drug lord''s attention. Bond also gains the trust of Lupe Lamora, Sanchez''s abused mistress, whom Bond had previously rescued from Krest''s men. Instead of assassinating Sanchez outright, Bond manipulates the drug lord''s intense paranoia. He plants the stolen cartel cash aboard Krest''s vessel, convincing Sanchez that Krest is a traitor who stole from him. Sanchez brutally executes Krest inside a decompression chamber, cementing Bond''s position as a trusted insider within the cartel. Q joins Bond in Isthmus in an unofficial capacity, bringing useful field equipment disguised as everyday items. Bond accompanies Sanchez to his secret cocaine processing facility, hidden beneath a remote religious temple run by a corrupt televangelist. At the facility, Bond learns that Sanchez is dissolving cocaine in gasoline to ship it undetected across international borders in tanker trucks. However, Dario recognizes Bond from Florida and exposes his identity to Sanchez. Bond sets fire to the laboratory and escapes as a chaotic firefight breaks out. Bond pursues Sanchez''s convoy of gas-filled tankers through the desert in a dramatic vehicular chase, destroying several trucks along the way. During a violent struggle aboard the final burning tanker, Sanchez corners Bond with a machete. Bond pulls out a cigarette lighter given to him by Felix and Della as a wedding present, igniting the gasoline on Sanchez and setting the drug lord ablaze. Sanchez stumbles into the leaking tanker, which explodes and kills him. A recovering Felix calls Bond from the hospital to share the news of his recovery, and Bond celebrates his victory with Pam at Sanchez''s former villa.',
       'https://www.youtube.com/watch?v=GlyacuZs5kM',
       '13 June 1989, Odeon Leicester Square, London ',
       UUID_TO_BIN('9d6bfb11-eed5-4a37-a770-cb2bc3847910'),
       'Timothy Dalton',
       UUID_TO_BIN('29e4e57a-000c-486f-9bf7-4ce84899df6c'),
       'Key West, Florida; Churubusco Studios in Mexico City, Isla Mujeres, Cancun, Veracruz, Mexicali, near Alcapuco, near Toluca, Mexico',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Goldeneye (1995)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('06d701ab-f89f-4b57-9c6e-f43628cc4e6d'),
       17,
       'Goldeneye',
       'Years after a joint mission goes wrong and results in the apparent execution of his fellow agent Alec Trevelyan, James Bond investigates the theft of a sophisticated stealth helicopter and a secret Soviet electromagnetic pulse satellite weapon known as GoldenEye. Rogue general Arkady Ourumov and assassin Xenia Onatopp destroy a remote Siberian tracking station using the weapon, leaving computer programmer Natalya Simonova as the sole survivor. Bond travels to post-Cold War St. Petersburg and uncovers that the crime syndicate behind the attack is led by Trevelyan, who faked his death and now seeks vengeance against Britain for its past betrayal of his Cossack parents. Bond and Natalya join forces to track Trevelyan to a hidden dish in Cuba, stopping his plot to cripple London''s financial infrastructure with an orbital pulse and defeating him atop the giant satellite antenna.',
       'The story opens nine years in the past at a Soviet chemical weapons facility in Arkhangelsk, where James Bond works alongside fellow double-0 agent Alec Trevelyan, 006. The operation goes awry when the base commander, General Arkady Ourumov, corners the agents and executes Trevelyan in front of Bond. Bond manages to destroy the facility and make a dramatic escape by catching a falling plane mid-air. In the present day, following the collapse of the Soviet Union, Bond is evaluated by MI6''s new chief, M, who questions his place in a post-Cold War intelligence landscape. Bond travels to Monte Carlo to investigate Xenia Onatopp, a sadistic operative for the Janus crime syndicate. Onatopp and General Ourumov hijack a prototype French Eurocopter Tiger helicopter that is completely immune to electromagnetic interference. The duo flies the stolen chopper to a remote satellite facility in Severnaya, Russia. There, they steal the access keys to GoldenEye, a pair of secret Soviet military satellites capable of firing a high-altitude electromagnetic pulse that destroys all electronics within range. To cover their tracks, Ourumov fires one of the GoldenEye satellites at the station itself, detonating an EMP that wipes out the facility and brings down a responding jet fighter. A computer programmer named Natalya Simonova survives the Severnaya attack and escapes to St. Petersburg. MI6 sends Bond to St. Petersburg to investigate the Janus syndicate and its connection to the satellite theft. With the help of ex-KGB agent Valentin Zukovsky, Bond secures a meeting with the head of Janus. Bond is stunned to discover that Janus is none other than Alec Trevelyan, who survived the Arkhangelsk operation with facial scars. Trevelyan reveals his true heritage as a Lienz Cossack whose parents were betrayed by the British government to Stalin''s forces after World War II, driving his lifelong desire for revenge against Britain. Trevelyan traps Bond and Natalya inside the stolen Eurocopter, setting its missiles to fire on itself, but Bond manages to eject them to safety. Upon landing, they are captured by Russian military authorities, but Ourumov kills the Russian Defense Minister and frames Bond. Bond escapes through the streets of St. Petersburg in a hijacked military tank, crushing vehicles and tearing through buildings to pursue Ourumov, who has kidnapped Natalya. Bond intercepts Trevelyan''s armored train, killing Ourumov and rescuing Natalya, though Trevelyan escapes aboard the train after setting a timer to detonate the carriage. Bond uses his Q-branch laser watch to cut a hole in the floor and escape with Natalya seconds before the explosion. Natalya traces the signal controlling the second GoldenEye satellite to a remote jungle region in Cuba. Bond and Natalya fly to the area with the help of CIA agent Jack Wade, but their plane is shot down over the jungle. On the ground, Onatopp ambushes Bond, but Bond shoots down her helicopter, pinning her to a tree branch with her harness harness line and killing her. Bond and Natalya discover a hidden lake that drains away to reveal a massive satellite dish antenna beneath the water''s surface. Inside the hidden control base, Natalya hacks into the computer system and reprograms the GoldenEye satellite to force it into a re-entry orbit where it will burn up in the atmosphere. Trevelyan reveals his grand plan to rob the Bank of England electronically and then detonate GoldenEye over London, wiping out all financial records and plunging Britain into economic chaos while erasing all traces of his theft. Bond engages in a brutal hand-to-hand fight with Trevelyan high above the dish on the antenna''s cradle platform. Bond overpowers Trevelyan and drops him hundreds of feet down onto the floor of the dish below. Natalya joins Bond in a helicopter as the facility''s fuel tanks explode, destroying the dish apparatus, which collapses on top of Trevelyan. Bond and Natalya land safely in a secluded clearing, where Jack Wade and a squad of US Marines arrive to retrieve them.',
       'https://www.youtube.com/watch?v=tF8t5iheM5M',
       '13 November 1995, Radio City Music Hall, New York City, NY, USA',
       UUID_TO_BIN('feebc4f0-3b5b-4378-a5fa-e56f6baf754a'),
       'Pierce Brosnan',
       UUID_TO_BIN('04f63e27-2f0e-456d-bbac-a8148de87088'),
       'Monte Carlo, Monaco; near Thorenc, France; St. Petersburg, Russia; Nene Valley, Peterborough, London, Leavesden Studios, England; Puerto Rico; Locarno, Switzerland',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Tomorrow Never Dies (1997)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('28b1807d-93cc-4078-ad3a-44f00375d3dd'),
       18,
       'Tomorrow Never Dies',
       'When megalomaniacal media mogul Elliot Carver uses a stealth ship and a stolen GPS encoder to provoke a military conflict between Great Britain and China, James Bond is dispatched to investigate Carver''s global news network. Partnering with skilled Chinese intelligence agent Wai Lin, Bond uncovers Carver''s scheme to ignite World War III in exchange for exclusive broadcasting rights in China. The two agents infiltrate Carver''s radar-invisible stealth vessel in the South China Sea, destroy the ship, defeat Carver''s forces, and prevent a devastating nuclear exchange between the two nations.',
       'The film begins at a terrorist arms bazaar near the Russian border, where James Bond covertly gathers intelligence for MI6. When the British military launches a missile attack on the site, Bond discovers two nuclear torpedoes mounted on a jet fighter and hijacks the aircraft, flying it away just before the base explodes. Meanwhile, Elliot Carver, head of the massive Carver Media Group Network, initiates a plot to fabricate global breaking news. Carver''s henchman, techno-terrorist Henry Gupta, uses a stolen GPS encoder to tamper with the navigation systems of the British frigate HMS Devonshire, steering it off course into Chinese-controlled waters in the South China Sea. Carver''s stealth ship, commanded by Mr. Stamper, sinks the frigate with a sea drill, shoots down a responding Chinese fighter jet, and steals a nuclear missile from the sunken British vessel, making it appear that both nations attacked each other. With international tension rising and Britain threatening war against China, M sends Bond to Hamburg to investigate Carver, as Carver''s news network broke the story of the frigate''s sinking before MI6 even received official confirmation. In Germany, Bond reconnects with Paris Carver, Elliot''s wife and an old flame of Bond''s. Bond steals back the stolen GPS encoder from Carver''s media headquarters during a product launch event. Furious at the breach, Carver orders the execution of his wife for aiding Bond. Bond returns to his hotel room to find Paris murdered by professional assassin Dr. Kaufman. Bond overpowers Kaufman, escapes Carver''s thugs in a high-speed chase through a parking garage using a remote-controlled BMW, and delivers the GPS encoder to Q''s team for analysis. Analysis of the encoder proves that the HMS Devonshire was deliberately off course when it was attacked. Bond travels to the South China Sea to investigate the shipwreck alongside Wai Lin, a top operative for the Chinese Ministry of State Security who is also looking into Carver''s operations. The two agents dive to the sunken frigate and confirm that one of its nuclear cruise missiles was stolen. Upon surfacing, they are captured by Stamper and taken to Carver''s headquarters in Saigon. Bond and Wai Lin escape by jumping off Carver''s skyscraper while handcuffed together, leading to a motorcycle chase through the streets and rooftops of Saigon while evading a armed helicopter. Recognizing Carver''s true objective, Bond and Wai Lin pool their resources to stop him. They locate Carver''s stealth vessel anchored in Ha Long Bay, which remains invisible to military radar due to its specialized radar-absorbent hull. They board the stealth ship to plant explosives, intending to disable its cloaking capability and reveal its location to both the British and Chinese navies. Wai Lin is captured by Carver, but Bond manages to detonate a series of charges, blowing a hole in the stealth ship''s hull and exposing its position on radar to nearby warships. As the British navy opens fire on the newly visible vessel, a chaotic firefight erupts on board. Carver boasts that his ultimate goal is to launch the stolen nuclear missile at Beijing, wiping out the Chinese government so a rogue general can take power and grant Carver exclusive fifty-year broadcasting rights throughout China. Bond corners Carver and shoves him into the path of the ship''s massive sea drill, killing him. Bond then fights Stamper on the missile platform, trapping Stamper beneath the nuclear missile''s cradle before the weapon ignites. Bond dives clear with the rescued Wai Lin as the stealth ship explodes and sinks. Bond and Wai Lin share a romantic moment among the wreckage while waiting for the British navy to rescue them.',
       'https://www.youtube.com/watch?v=ETAYpg0MFPw',
       '9 December 1997, Odeon Leicester Square, London',
       UUID_TO_BIN('b7ba3a37-a5ad-40ec-8775-86ceaea8f20c'),
       'Pierce Brosnan',
       UUID_TO_BIN('39b37032-e49a-43a3-9973-94ee8e1bd6b3'),
       'Bangkok, Thailand; Hamburg, Germany; the Pyrenees, France; Baja Studios, Mexico; Sugarloaf Airfield, Florida, USA; London, Stoke Poges Golf Club, Eon Studios at Frogmore, Hertforshire and Pinewood Studios, Buckinghamshire, Oxford, Stansted Airport, UK',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  The World Is Not Enough (1999)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8ddc2a5a-c855-4768-9b70-3a3d383e621b'),
       19,
       'The World Is Not Enough',
       'Following the assassination of British oil tycoon Sir Robert King inside MI6 headquarters, James Bond is assigned to protect King''s daughter and heiress, Elektra, who is constructing a strategic pipeline across Azerbaijan. MI6 suspects the attack was ordered by Renard, a terrorist notorious for having a bullet lodged in his brain that renders him incapable of feeling physical pain. Partnering with nuclear physicist Dr. Christmas Jones, Bond uncovers a shocking conspiracy: Elektra has teamed up with her former kidnapper Renard to sabotage competing pipelines by causing a nuclear meltdown in the Bosporus. Bond rescues M from Elektra''s grasp, defeats Renard inside a sunken nuclear submarine, and kills Elektra to secure the region''s energy supply.',
       'The story begins in Bilbao, Spain, where James Bond meets with a Swiss banker to recover money belonging to Sir Robert King, a wealthy oil industrialist and close personal friend of M. After escaping an ambush, Bond returns the cash to MI6 headquarters in London. However, the money has been rigged with a micro-transmitter that triggers an explosive inside the building, killing Sir Robert King. Bond pursues the assassin along the River Thames in Q''s jet boat, ending in a chase to the Millennium Dome where the assassin kills herself rather than face interrogation. Bond investigates King''s death and suspects the involvement of Renard, a former KGB agent turned terrorist who previously kidnapped King''s daughter, Elektra. Renard survived a past assassination attempt by 009, leaving a bullet embedded in his brain that gradually deadens his senses, making him immune to pain and granting him unusual physical endurance. Bond travels to Azerbaijan to protect Elektra, who has taken over her father''s massive pipeline project through the Caucasus. While inspecting the construction route with Elektra, they are attacked by armed parahawk flyers, deepening Bond''s suspicion that she remains a primary target. Traveling to Kazakhstan, Bond visits a former Soviet nuclear test site where weapons are being decommissioned. There, he meets Dr. Christmas Jones, an American nuclear physicist supervising the removal of weapons-grade plutonium. Renard infiltrates the facility, steals a nuclear warhead, and places a rod of weapons-grade plutonium inside a inspection device running through Elektra''s oil pipeline. Bond and Dr. Jones enter the pipeline to disarm the device, realizing that Renard used the bomb as a distraction to conceal his true theft of the raw plutonium. When the pipeline section explodes, Bond and Christmas fake their deaths to catch the conspirators off guard. Bond travels to Istanbul and uncovers the true nature of the plot. Elektra was not an innocent victim of Renard''s past kidnapping, but rather developed Stockholm syndrome and partnered with him to take control of her father''s empire and avenge his lack of ransom payment. Elektra captures M, holding her hostage in Maiden''s Tower, while Renard boards a hijacked nuclear submarine in the Bosporus. Their master plan is to insert the stolen plutonium into the submarine''s nuclear reactor, causing a catastrophic meltdown that will contaminate Istanbul, destroy competing Bosphorus-routed pipelines, and leave Elektra with a total monopoly over Western Europe''s oil supply. Bond infiltrates Maiden''s Tower, frees M, and confronts Elektra. When Elektra refuses to call off Renard, Bond shoots and kills her. Bond then dives into the waters of the Bosporus to board the sinking nuclear submarine. Inside the flooded vessel, Bond engages in a brutal fight with Renard in the reactor room. Bond overpowers the terrorist and impales him with the reactor''s fuel rod, preventing the meltdown. Bond and Dr. Jones escape the submarine as it breaks apart, surfacing safely in Istanbul, where they spend a romantic evening together.',
       'https://www.youtube.com/watch?v=a3y2jD57KRo',
       '8 November 1999, Bruin & Fox Theatre, Los Angeles, USA',
       UUID_TO_BIN('f196186f-e769-4808-8222-f86cc90eeab6'),
       'Pierce Brosnan',
       UUID_TO_BIN('31283991-54c6-4746-9fd5-bfa4c466fa55'),
       'Baku, Azerbaijan; Istanbul, Turkey; Chamonix, France; Tudela and Bilbao, Spain; offshore Bahamas; Snowdonia National Park, Wales; Hankley Common, Surrey, Swindon, London and Pinewood Studios, England; Eilean Donan Castle, Scotland',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Die Another Day (2002)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f555fa79-8c7a-46df-b178-649ae651065f'),
       20,
       'Die Another Day',
       'After a covert mission in North Korea goes wrong, James Bond is captured and imprisoned for fourteen months before being traded back to the West. Stranded without his double-0 status due to suspicions that he leaked information under torture, Bond goes rogue to track down the traitor who betrayed him. Following clues from Cuba to London, Bond investigates flamboyant British billionaire Gustav Graves and discovers that Graves is actually North Korean Colonel Moon, who reshaped his appearance using radical DNA replacement therapy. Partnering with NSA operative Jinx Johnson, Bond uncovers Graves'' plan to use Icarus, a massive orbital solar satellite, to vaporize the Korean Demilitarized Zone and clear the path for an invasion of South Korea. Bond infiltrates Graves'' Ice Palace, survives a high-tech battle in the skies, and kills Graves to avert global war.',
       'The film opens in North Korea, where James Bond infiltrates a military base posing as a diamond smuggler trading blood diamonds for weaponry. Bond confronts Colonel Tan-Sun Moon, who is using illegal sales to fund a private arsenal. During a high-speed hovercraft chase along the Demilitarized Zone, Moon falls over a cliff to his apparent death, but Bond is captured by Moon''s father, General Moon. Bond is imprisoned and tortured for fourteen months before being released in a prisoner exchange for Zao, a terrorist associate of Moon whose face was disfigured by diamonds during Bond''s initial mission. Upon returning to MI6, M revokes Bond''s double-0 status, suspecting he broke under interrogation and leaked classified intelligence. Determined to clear his name and find the true mole, Bond escapes custody in Hong Kong and tracks Zao to a gene-therapy clinic in Havana, Cuba. There, Bond discovers that patients undergo radical gene replacement therapy to alter their physical identities completely. Bond meets NSA operative Giacinta "Jinx" Johnson, who is also investigating the clinic. Bond confronts Zao at the facility, but Zao escapes before completing his treatment, leaving behind a pouch of conflict diamonds bearing the seal of British billionaire industrialist Gustav Graves. Bond returns to London to confront Graves, who has ostensibly made his fortune mining diamonds in Iceland and created a massive space mirror project called Icarus, designed to reflect sunlight to assist polar agriculture. Bond challenges Graves to a high-stakes fencing duel at a London club, which escalates into a brutal sword fight. Graves invites Bond to an exhibition of the Icarus project at his Ice Palace in Iceland. Reinstated by M, Bond travels to Iceland and receives a new Aston Martin equipped with adaptive camouflage technology from Q. At the Ice Palace, Bond meets Graves'' assistant, Miranda Frost, who is secretly an MI6 double agent. Bond discovers that Graves is actually Colonel Moon, having survived his fall and transformed his appearance using the Cuban gene therapy. Moon plans to use Icarus not as an agricultural tool, but as an orbital solar laser capable of destroying defensive military positions. Bond discovers that Miranda Frost is the actual traitor who betrayed his identity in North Korea. Frost captures Jinx, while Bond escapes using his car''s high-tech weapons. In a fierce vehicular showdown across the frozen landscape, Bond defeats Zao, killing him with a falling ice chandelier, and rescues Jinx from a drowning chamber inside the melting Ice Palace. Graves and Frost escape aboard a military transport plane heading toward the Korean Peninsula, prompting Bond and Jinx to board the aircraft covertly in mid-air. Aboard the aircraft, Graves activates the Icarus laser beam, carving a path through the minefields of the Demilitarized Zone to prepare for a North Korean invasion of the South. General Moon attempts to stop his son, but Graves murders his father in cold blood. Jinx engages Miranda Frost in a sword fight in the cockpit, stabbing and killing the traitorous operative. Meanwhile, Bond fights Graves, who is wearing a high-tech electro-shock suit that controls the satellite''s targeting system. Bond pulls Graves'' parachute rip cord, pulling the villain into the plane''s jet engine and killing him. The Icarus beam deactivates, and Bond and Jinx escape the crashing plane aboard a helicopter loaded with Graves'' stolen diamonds, surviving the ordeal to enjoy a secluded retreat together.',
       'https://www.youtube.com/watch?v=W43YPzQIHT0',
       '18 November 2002, The Royal Albert Hall, London',
       UUID_TO_BIN('fdfee862-d4aa-4d64-8ec2-c1cf1477ed21'),
       'Pierce Brosnan',
       UUID_TO_BIN('dd4cad36-a151-4e7c-8257-3a460aee0067'),
       'Hawaii, USA; Aldershot, London, Eden Project, Cornwall, Gloucestershire, Chinnor, Burford, Oxfordshire & Pinewood Studios, England;Penbryn Beach, Ceredigion, Wales; Iceland; Cadiz, Spain',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Casino Royale (2006)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('8218a578-0622-4d75-a86c-1501a3e48afc'),
       21,
       'Casino Royale',
       'After earning his double-0 status with two targeted assassinations, newly minted British secret agent James Bond is tasked with dismantling the financial network of Le Chiffre, a private banker who funds international terrorist organizations. When Bond thwarts Le Chiffre''s plan to destroy a prototype airliner, the banker loses millions of dollars of his warlord clients'' money and arranges a high-stakes Texas Hold ''em tournament at Casino Royale in Montenegro to recoup his losses. Accompanied by Vesper Lynd, a treasury official overseeing the government''s buy-in funds, Bond enters the game to bankrupt Le Chiffre and force him into government protection. Bond survives poisonings, betrayals, and brutal torture, ultimately winning the tournament, only to discover that Vesper is harboring a tragic secret that will reshape his life forever.',
       'The film begins in Prague, where MI6 operative James Bond earns his 007 designation by completing two required assassinations, including a traitorous section chief. Bond''s first official double-0 assignment leads him to Madagascar in pursuit of a bomb-maker named Mollaka. Following a intense parkour foot chase through a construction site, Bond kills Mollaka inside a foreign embassy and recovers his mobile phone. Clues on the device point Bond to the Bahamas, where he encounters Alex Dimitrios, an associate of Le Chiffre, a brilliant mathematical mind who operates as a private banker for global terrorist syndicates. Bond uncovers Le Chiffre''s scheme to short-sell stock in Skyfleet, an aerospace company, right before detonating a prototype airliner at Miami International Airport. Bond travels to Miami and intercepts Le Chiffre''s hired assassin on the tarmac, preventing the destruction of the aircraft and causing the stock short-sale to fail completely. Having lost over one hundred million dollars belonging to his dangerous warlord clients, Le Chiffre sets up a high-stakes Texas Hold ''em poker tournament at the Casino Royale in Montenegro to recover the lost funds before his clients murder him. M dispatches Bond to enter the tournament, recognizing that 007 is MI6''s best card player. British Treasury representative Vesper Lynd joins Bond to manage the ten-million-dollar stake provided by the government. Upon arriving in Montenegro, they meet local MI6 contact René Mathis. During the grueling tournament, Bond initially misreads Le Chiffre''s tell and loses his entire chip stack. Vesper refuses to authorize an additional five-million-dollar rebuy, but CIA agent Felix Leiter steps in to finance Bond in exchange for the CIA taking custody of Le Chiffre afterward. Surviving a cardiac arrest caused by digitalis poison placed in his martini, Bond returns to the table and wins the final hand, taking the entire hundred-and-fifteen-million-dollar pot. Shortly after the victory, Le Chiffre kidnaps Vesper to lure Bond into a trap. Bond pursues them in his Aston Martin, but swerves to avoid running over a bound Vesper in the road, crashing and flipping his vehicle. An injured Bond is captured and taken to an abandoned villa, where Le Chiffre subjects him to brutal physical torture to extract the bank account password for the winnings. Before Le Chiffre can kill him, Mr. White, an operative representing a mysterious shadow syndicate, enters the room and shoots Le Chiffre dead for bringing unwanted attention and losing client money. Bond wakes up in a hospital on Lake Como, recovering alongside Vesper, with whom he has fallen deeply in love. Bond decides to resign from MI6 to travel the world with her, and they arrive in Venice. However, Bond soon learns from M that the tournament winnings were never deposited into the Treasury account. Bond pursues Vesper through the streets of Venice, watching her trade the money to armed operatives. A gunfight erupts inside a decaying, sinking Venetian palazzo. Bond kills the gunmen, but Vesper locks herself inside an elevator cage as the building sinks into the canal, drowning despite Bond''s frantic efforts to save her. M informs Bond that Vesper''s former lover was being held hostage by Mr. White''s organization, forcing her to trade the money for Bond''s life. Realizing Vesper sacrificed herself to save him, Bond cold-heartedly buries his emotions and rededicates himself to his duty as a secret agent. Using a phone contact left behind by Vesper, Bond tracks Mr. White to an estate in Lake Como. Bond shoots White in the leg, approaches the wounded operative with a submachine gun, and introduces himself with his iconic catchphrase: Bond, James Bond.',
       'https://www.youtube.com/watch?v=l_c4uGxMdws',
       '14 November 2006, Odeon Leicester Square, London',
       UUID_TO_BIN('26d5b751-600a-4371-af30-5b562494f454'),
       'Daniel Craig',
       UUID_TO_BIN('04f63e27-2f0e-456d-bbac-a8148de87088'),
       'Modrany & Barrandov Studios, Prague and Karlovy Vary, Czech Republic; New Providence and Paradise Island, Bahamas; Dunsfold Aerodrome, Black Park, Buckinghamshire; Pinewood Studios, England; Lake Como & Venice, Italy',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Quantum Of Solace (2008)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('32b40321-da45-4ff3-b417-2b2d79c10de9'),
       22,
       'Quantum Of Solace',
       'Picking up immediately after the events of Casino Royale, a grief-stricken James Bond seeks revenge for the death of Vesper Lynd while investigating the mysterious organization known as Quantum. Following a trail that leads from Siena to Haiti and Austria, Bond crosses paths with Dominic Greene, a ruthless entrepreneur posing as an environmentalist. Greene is secretly conspiring with exiled Bolivian General Medrano to overthrow the country''s government in exchange for a desolate tract of desert. Partnering with Camille Montes, a Bolivian intelligence agent seeking her own revenge against Medrano, Bond discovers that Greene''s plan is not to seize oil, but to monopolize Bolivia''s entire fresh water supply. Bond and Camille infiltrate Greene''s desert hotel compound, dismantle his cartel scheme, and avenge their personal losses before Bond finally finds closure regarding Vesper''s betrayal.',
       'The film opens directly after the conclusion of Casino Royale, with James Bond engaging in a high-speed car chase along the roads of Lake Como while transporting the captured Mr. White in his trunk. Bond arrives at an MI6 safehouse in Siena, Italy, where he and M interrogate White regarding his shadowy employer. White reveals that their organization, Quantum, has operatives placed inside every major government and intelligence agency worldwide. Before White can elaborate, M''s personal bodyguard, Craig Mitchell, exposes himself as a double agent, shooting at M and aiding White''s escape. Bond pursues Mitchell across the rooftops and inside the scaffolding of Siena, ultimately killing the traitor after a dangerous struggle. Tracing marked bills from Mitchell''s bank account, Bond travels to Port-au-Prince, Haiti, to track down a hitman named Slate. After killing Slate in self-defense, Bond assumes his identity and meets Camille Montes, a Bolivian operative who mistakes Bond for Slate. Camille is involved with Dominic Greene, a French businessman who heads an environmental organization named Greene Planet. Greene is secretly using his public eco-friendly persona as a front for Quantum''s covert operations. Bond follows Greene to an open-air opera performance of Tosca in Bregenz, Austria. Inside the opera house, Bond eavesdrops on an earpiece-transmitted Quantum conference meeting, identifying several high-ranking international members by snapping photos of them leaving the theater in disgust after he interrupts their frequency. Greene strikes a deal with General Medrano, a exiled Bolivian military officer who murdered Camille''s family years prior. Greene promises to back a military coup to install Medrano as the ruler of Bolivia in exchange for a seemingly worthless stretch of desert land. Believing Greene wants to drill for oil, the CIA agrees to turn a blind eye to the coup to protect American energy interests in South America. Meanwhile, M revokes Bond''s passports and credit cards after he is framed for the death of a British contact, prompting Bond to seek assistance from his trusted friend René Mathis. Bond and Mathis fly to Bolivia, where they are met by Strawberry Fields, an operative from the British consulate sent to bring Bond back to London. Bond seduces Fields and attends Greene''s fundraising party, where he rescues Camille from Greene''s clutches. Later that night, corrupt local police officers pulled over Bond''s car and fatally wound Mathis, framing Bond for his murder. Bond then meets with CIA agent Felix Leiter, who quietly tips him off to Greene''s location in the Atacama Desert. Returning to his hotel, Bond finds Fields murdered, covered completely in crude oil in a sinister warning from Quantum. Bond and Camille fly a vintage plane over the desert to survey Greene''s land, but they are shot down by a fighter jet, forcing them to parachute into a deep sinkhole. Underground, Bond and Camille discover that Quantum has dammed up Bolivia''s subterranean water veins, intending to control over eighty percent of the nation''s fresh water and force the government to buy it back at exorbitant prices. Bond and Camille infiltrate Greene''s eco-hotel compound in the Atacama Desert during a meeting between Greene and General Medrano to finalize the coup contract. A battle erupts as Bond sets off a series of fuel tank explosions inside the building. Camille confronts General Medrano, shooting and killing him to avenge her murdered family. Bond corners Greene amidst the burning ruins, interrogating him about Quantum''s leadership before leaving him stranded in the middle of the desert with nothing to drink except a can of motor oil. Bond drives Camille to a train station, where they part ways after sharing a brief moment of mutual understanding over their shared grief. Bond then travels to Kazan, Russia, where he confronts Vesper''s former lover, Yusef Kabira, a Quantum agent who seduces female intelligence operatives to extract secret information. Instead of killing Kabira, Bond spares his life and turns him over to M and MI6, finally letting go of his anger over Vesper''s death and fully committing to his role as a double-0 agent.',
       'https://www.youtube.com/watch?v=RmFipSJxJD4',
       '29 October 2008, Odeon Leicester Square, London',
       UUID_TO_BIN('62c7f890-9896-433a-acc1-a0e4827bb752'),
       'Daniel Craig',
       UUID_TO_BIN('cfba2942-ac6d-405c-8a82-bccb2a2ef81a'),
       'Bruneval Barracks, Montgomary Lines in Aldershot, Farnborough Airport, Bodyflight, Bedford, Virgin’s ‘The Base’ Crawley. The Reform Club, London, Pinewood Studios, England; Howard Airport, Casa Vejo, Panama City, Coco Solo, Cabra Island, Colon, Panama; The ESO Paranal, Atacama desert, Chile; Torre di Talamonaccio, Siena, Lake Garda, Carrera, Italy; Bregenz, Austria; Baja California, Mexico',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Skyfall (2012)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('2a85118c-7fd2-4096-9668-01fd8320ab17'),
       23,
       'Skyfall',
       'After a botched operation in Istanbul leaves James Bond presumed dead and a hard drive containing the identities of embedded NATO agents stolen, MI6 comes under relentless cyberattack. Bond emerges from hiding to support M when MI6 headquarters is bombed, leading him to Raoul Silva, a former MI6 operative and brilliant cyberterrorist seeking personal vengeance against M for abandoning him years earlier. Failing to pass standard physical fitness tests, an aging Bond relies on his instincts and returning field support, including a new Q and agent Eve Moneypenny. Bond retreats with M to his isolated childhood home in Scotland, Skyfall, setting a series of improvised traps to make a final stand against Silva and his mercenary army. Though Bond kills Silva, M succumbs to her wounds, leaving Bond reinstated under a new M to carry on his duties.',
       'The film opens in Istanbul, where James Bond and fellow field agent Eve pursue an assassin named Patrice, who has stolen a hard drive containing the true identities of undercover NATO agents placed inside terrorist cells worldwide. During a frantic chase atop a moving train, M orders Eve to take a risky shot at Patrice. Eve accidentally shoots Bond, causing him to plunge off a railway bridge into a river below, where he is presumed dead. With the mission compromised, M faces intense political pressure from Gareth Mallory, the Intelligence and Security Committee Chairman, who urges her to retire honorably as MI6 undergoes a parliamentary inquiry regarding its relevance in the modern digital age. Months later, a cyberterrorist hacks into MI6''s network, leaking the identities of NATO agents online and detonating a deadly explosion at MI6 headquarters in London. Seeing news of the attack while living off the grid in tropical isolation, a physically impaired and disillusioned Bond returns to London. Despite failing his medical and marksmanship evaluations, M reinstates Bond to active duty to track down Patrice. Armed with a radio transmitter and a personalized palm-print pistol provided by the young new Q, Bond travels to Shanghai, where he watches Patrice execute an target inside a skyscraper. Patrice falls to his death during a fight before Bond can interrogate him, leaving Bond with a single clue: a casino chip from Macau. In Macau, Bond meets Sévérine, a mysterious woman connected to Patrice''s employer. Recognizing that she is terrified of her boss, Bond promises to protect her if she leads him to him. They travel aboard her yacht to an abandoned island off the coast of Macao, where they are captured by Raoul Silva, a cyberterrorist and former MI6 agent named Tiago Rodriguez. Silva reveals that he once worked under M in Hong Kong, but when he engaged in unauthorized hacking, M traded him to Chinese authorities in exchange for a smooth diplomatic transition, leaving him to endure brutal torture and a failed cyanide suicide attempt that disfigured his mouth. Driven by an intense hatred for M, Silva executes Sévérine, but Bond manages to overpower Silva''s guards and activate his Q transmitter, summoning MI6 helicopters to take Silva into custody. Back in London, Silva is locked inside a high-tech containment cell beneath MI6''s temporary subterranean bunker. However, Q accidentally triggers a malware program hidden inside Silva''s laptop while attempting to crack its encryption, opening all security doors and allowing Silva to escape into the London Underground network. Bond pursues Silva through crowded train tunnels, realizing that Silva intentionally allowed himself to be captured as part of a elaborate plan to assassinate M during her parliamentary hearing. Bond arrives at the inquiry room just as Silva and his disguised henchmen open fire, creating a distraction with Mallory and Eve to hustle M to safety. Recognizing that Silva can track them anywhere in the digital world, Bond takes M off the grid, driving her in his classic Aston Martin DB5 to his remote, abandoned childhood estate in the Scottish Highlands, known as Skyfall. Rejoining Kincade, the estate''s elderly gamekeeper, Bond, M, and Kincade arm themselves with old hunting rifles and improvise booby traps throughout the house to prepare for Silva''s arrival. When Silva''s initial assault team arrives, Bond and his allies kill the mercenaries, but Silva arrives shortly after in a heavy attack helicopter, firing heavy weaponry that devastates the estate and sets Skyfall ablaze. Bond detonates gas canisters inside the house to destroy the helicopter, while Kincade leads M through a hidden tunnel toward an ancient chapel on the grounds. A wounded M reaches the chapel, where Silva corners her, placing his head against hers and begging her to end both of their lives with a single bullet. Bond arrives just in time, throwing a hunting knife into Silva''s back and killing him. However, M collapses from a gunshot wound sustained earlier during the siege and dies in Bond''s arms. Following the tragedy, Bond returns to London, where Gareth Mallory assumes the role of the new M, Eve transitions out of field work to become M''s secretary under her full name Eve Moneypenny, and Bond accepts his next mission, fully committed to serving queen and country once again.',
       'https://www.youtube.com/watch?v=HWWe4wm7JcE',
       '23 October 2012, The Royal Albert Hall, London',
       UUID_TO_BIN('f7331faa-38ff-4180-9b38-cdde54abc70a'),
       'Daniel Craig',
       UUID_TO_BIN('91992cf2-4368-4445-9555-25546ea6922b'),
       'Longcross & Pinewood Studios, London locations, and Hankley Common, Surrey, England; Glencoe, Scotland; Shanghai, China; Istanbul, Fethiye, Adana, and Calis Beach, Turkey',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Spectre (2015)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('0d7d18ba-04a5-4f64-a720-8cbf39692862'),
       24,
       'Spectre',
       'Following a posthumous directive from the previous M, James Bond embarks on an unauthorized mission to Mexico City and Rome, where he uncovers the existence of Spectre, a global criminal syndicate. Back in London, the double-0 program faces shutdown from Max Denbigh, the head of the new Joint Intelligence Service who seeks to establish Nine Eyes, a global surveillance network. Bond tracks down Dr. Madeleine Swann, the daughter of his former enemy Mr. White, and together they trace Spectre to a desert stronghold in Morocco. There, Bond meets Spectre''s leader, Ernst Stavro Blofeld, who reveals himself as Bond''s foster brother and the mastermind behind all of Bond''s past personal tragedies. Returning to London, Bond thwarts the Nine Eyes activation, saves Madeleine from the booby-trapped former MI6 headquarters, and chooses to spare Blofeld before walking away from MI6.',
       'The film opens during the Day of the Dead festival in Mexico City, where James Bond carries out a rogue assassination mission based on a posthumous video message left by the previous M. After stopping a terrorist bombing and killing assassin Marco Sciarra in a chaotic helicopter fight, Bond retrieves Sciarra''s ring, which is engraved with an octopus symbol. In London, the new M reprimands Bond for creating an international incident and grounds him. Simultaneously, MI6 faces dissolution as Max Denbigh, codenamed C, merges British intelligence services and pushes for the Nine Eyes alliance—an invasive, automated global surveillance agreement between nine nations. Ignoring his suspension, Bond enlists Q and Moneypenny to help him off the record and travels to Rome for Sciarra''s funeral. After saving Sciarra''s widow, Lucia, Bond uses Sciarra''s ring to infiltrate a clandestine meeting of the syndicate. He witnesses the ruthlessness of the group''s leader, Franz Oberhauser, and is forced to flee after being recognized. Pursued through Rome by Spectre enforcer Mr. Hinx, Bond escapes into the Tiber River and directs Moneypenny to look into the Pale King—who turns out to be his old Quantum adversary, Mr. White. Bond tracks a dying Mr. White to a cabin in Austria, where White is suffering from fatal thallium poisoning planted by Spectre. Before committing suicide, White agrees to give Bond a lead if Bond promises to protect his daughter, Dr. Madeleine Swann. Bond locates Madeleine at a private medical clinic, but she is kidnapped by Hinx and his men. Bond rescues her following an intense aircraft and vehicular chase, and together they meet Q in Austria to analyze Sciarra''s ring. Digital analysis proves that Bond''s former enemies—Le Chiffre, Dominic Greene, Raoul Silva, and Mr. White—were all connected to the overarching Spectre network. Madeleine reveals that the name L''Americain, left by her father, refers to a hotel suite in Tangier, Morocco. Inspecting the suite, Bond discovers a hidden room containing maps, coordinates, and recordings left by Mr. White. Following the coordinates across the North African desert aboard a train, Bond and Madeleine survive a brutal fight with Mr. Hinx before arriving at a massive, state-of-the-art facility situated inside a desert meteor crater. Inside the base, Bond confronts Franz Oberhauser, who reveals that he faked his death years ago and took the name Ernst Stavro Blofeld. Blofeld reveals he is Bond''s foster brother, having resented the affection his father showed to the orphaned Bond, which drove him to murder his father and build a global network to systematically ruin Bond''s life. Blofeld also discloses that Spectre is funding C and orchestrating terrorist attacks worldwide to guarantee the approval of Nine Eyes, giving Spectre total, unchecked surveillance over global intelligence. Blofeld subjects Bond to neuro-surgical torture, but Bond uses an explosive watch crafted by Q to break free. Bond and Madeleine blow up the facility''s fuel supplies, destroying the entire compound, and escape back to London. In London, Bond, M, Q, Moneypenny, and Bill Tanner team up to prevent Nine Eyes from going live. M confronts C, and during a physical struggle, C falls to his death as Q succeeds in shutting down the system. Meanwhile, Bond is ambushed and brought to the ruined, condemned MI6 building, which Blofeld has rigged with explosives. Blofeld gives Bond a countdown to either escape or find Madeleine hidden within the crumbling structure. Bond locates Madeleine in time, and they escape on a boat via the Thames just as the building collapses. Bond pursues Blofeld''s getaway helicopter, shooting it down onto Westminster Bridge. Confronting a wounded Blofeld on the bridge, Bond decides to spare his life, leaving him to be arrested by M. Bond retires from field service and drives away into the distance with Madeleine in his restored Aston Martin DB5.',
       'https://www.youtube.com/watch?v=jDwXkDSuxBY',
       '26 October 2015, The Royal Albert Hall, London',
       UUID_TO_BIN('a7f9c888-5f81-494b-b1f6-fd50f8e12cab'),
       'Daniel Craig',
       UUID_TO_BIN('91992cf2-4368-4445-9555-25546ea6922b'),
       'Pinewood Studios, London locations, UK; Lake Altaussee, Obertilliach and Sölden, Austria; Rome, Italy; Mexico City, Mexico; Tangier, Erfoud and Sahara desert, Morocco',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  No Time To Die (2021)
 */
INSERT INTO movies (id, movie_number, title, short_description, long_description, trailer_url, world_premiere, music_id, james_bond_actor, director_id, locations, created_at, updated_at)
VALUES (
       UUID_TO_BIN('f1930593-6cae-45d0-a063-84582ac10fac'),
       25,
       'No Time To Die',
       'Five years after the capture of Ernst Stavro Blofeld, James Bond has retired from MI6 and is living a peaceful life in Jamaica. His tranquil existence is shattered when his old CIA friend Felix Leiter arrives asking for help to recover a kidnapped scientist, Valdo Obruchev. The mission reveals the existence of Heracles, a secret MI6 bioweapon containing targeted nanobots designed to kill specific DNA profiles upon contact. Bond discovers that a mysterious terrorist named Lyutsifer Safin has stolen the weapon to wipe out Spectre and mass-produce it for global distribution. Teaming up with Nomi, the agent who inherited his 007 designation, and reunited with his former love Madeleine Swann, Bond infiltrates Safin’s island fortress. After ensuring his loved ones are safe and opening the facility''s blast doors for a naval missile strike, Bond succumbs to his wounds and sacrifices his life to destroy the bioweapon forever.',
       'The film opens with a flashback showing a young Madeleine Swann surviving an attack at her snowy home by masked assassin Lyutsifer Safin, who murders her mother in retaliation for her father, Mr. White, poisoning his family. Safin spares young Madeleine after she falls through ice and he rescues her. Years later, following the events in Spectre, Bond and Madeleine are staying in Matera, Italy. After Bond visits the tomb of Vesper Lynd, he is ambushed by Spectre assassins. Believing Madeleine betrayed his location to the syndicate, a heart-broken Bond forces her onto a train and severs all ties with her. Five years later, Bond is living off the grid in Jamaica after retiring from active service. Meanwhile, a subterranean MI6 laboratory in London is raided by mercenaries who kidnap scientist Valdo Obruchev and steal Project Heracles, a classified bioweapon composed of microscopic nanobots that spread through physical contact and selectively kill individuals based on their genetic code. CIA operative Felix Leiter and State Department agent Logan Ash track Bond down in Jamaica, requesting his help to recover Obruchev from a Spectre gathering in Havana, Cuba. Bond agrees and travels to Havana, where he teams up with energetic local CIA contact Paloma. At the event, Obruchev triggers the nanobots under Safin''s secret orders, turning the weapon against the Spectre members present and killing them all while leaving Bond unharmed. Bond captures Obruchev, but Logan Ash reveals himself as a double agent working for Safin, fatally wounding Felix Leiter and fleeing with the scientist while Bond narrowly escapes the sinking ship. Bond returns to London and confronts M, who admits to creating Heracles as a clean targeted weapon, though it has now been hijacked and weaponized into an indiscriminate mass casualty threat. Bond meets Nomi, the field agent who was assigned the 007 title following Bond''s retirement. To locate Safin, Bond arranges an interrogation with an incarcerated Blofeld at Belmarsh Prison, who will only speak to his psychiatrist, Madeleine Swann. Before the interrogation, Safin corners Madeleine and forces her to apply a perfume laced with nanobots targeted specifically at Blofeld. Overcome with anxiety, Madeleine leaves the prison, but Bond touches her wrist before she departs. During the interrogation, Bond angrily grabs Blofeld, unknowingly transferring the nanobots from his hands to Blofeld, instantly killing the Spectre leader. Bond tracks Madeleine to her childhood home in Norway, where he learns she has a five-year-old daughter named Mathilde. Madeleine insists the child is not Bond''s, but before they can process the reunion, Safin''s mercenaries attack the property. Bond kills Ash and defending the family in a harrowing woodland chase, but Safin arrives in a helicopter and abducts Madeleine and Mathilde, taking them to his headquarters—a fortified World War II missile base on an island located between Japan and Russia. Assisted by Q and M, Bond and Nomi infiltrate Safin’s island stronghold using a tactical glider aircraft. Inside the base, they find a massive automated factory where Safin plans to mass-produce Heracles and broadcast targeted strains globally. Nomi kills Obruchev by pushing him into a vat of nanobots, while Bond rescues Madeleine and Mathilde. Nomi escorts Madeleine and Mathilde off the island aboard a boat, while Bond stays behind to clear the island''s heavy armored blast doors so British naval warships can destroy the facility with air strikes. Bond battles his way through Safin''s remaining guards and manually opens the blast doors, but Safin closes them again from a central control hub and ambushes Bond, shooting him multiple times. During their brutal struggle, Safin infects Bond with a permanent, customized strain of Heracles programmed to target the genetic code of Madeleine and Mathilde, meaning Bond can never touch either of them again without causing their immediate deaths. Bond kills Safin, reopens the blast doors, and climbs to the facility''s roof. Realizing he cannot return to the people he loves without endangering them, Bond speaks to Madeleine over the radio, expressing his love and accepting that Mathilde is indeed his daughter. As Madeleine tearfully bids him farewell, naval missiles strike the island, completely destroying the fortress and killing Bond, ensuring the bioweapon is permanently destroyed. Back in London, M, Q, Moneypenny, Nomi, and Tanner gather to drink a toast to Bond''s legacy, while Madeleine drives through Italy with Mathilde, telling her daughter the story of James Bond.',
       'https://www.youtube.com/watch?v=FREBR6FH1rg',
       '28 September 2021, Royal Albert Hall, London',
       UUID_TO_BIN('c8f05c81-3ccd-46ef-add5-c23ca0462488'),
       'Daniel Craig',
       UUID_TO_BIN('3e68940b-4aad-4912-a03f-14a07929f6e3'),
